Object.assign(window.TEM8_DICTIONARY, {"snacks":{"oxford":{"phon":"snæk","pos":"noun","senses":[{"en":"( informal ) a small meal or amount of food, usually eaten in a hurry","cn":"点心；小吃；快餐"},{"en":"( AustralE ) ( informal ) a thing that is easy to do","cn":"易办到的事；“小菜一碟”"}]}},"snobbish":{"media":{"uk":"media/uk/snobbish__gb_1.mp3","us":"media/us/snobbish__us_1.mp3"},"oxford":{"phon":"ˈsnɒbɪʃ","pos":"adjective","senses":[{"en":"thinking that having a high social class is very important; feeling that you are better than other people because you are more intelligent or like things that many people do not like","cn":"势利的；自命不凡的","ex":{"en":"She was quite snobbish about pop culture.","cn":"她对流行文化的态度很是势利。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(对自身社会地位、才智、品位等)过分自傲的，势利的","en":"If you describe someone as snobbish, you disapprove of them because they are too proud of their social status, intelligence, or taste.","ex":{"en":"They had a snobbish dislike for their intellectual and social inferiors","cn":"他们非常势利，不喜欢智力和社会地位不如自己的人。"}}]},"examples":[{"en":"Her family seems snobbish.","cn":"她家里人好像挺势利的。"}]},"sneer":{"oxford":{"phon":"snɪə(r)","pos":"verb","senses":[{"en":"to show that you have no respect for somebody by the expression on your face or by the way you speak","cn":"嘲笑；讥讽；嗤笑","ex":{"en":"He sneered at people who liked pop music.","cn":"他嘲笑喜欢流行音乐的人。"}},{"en":"an unpleasant look, smile or comment that shows you do not respect somebody/something","cn":"嘲笑；讥讽","ex":{"en":"‘And who are you, then?’ he asked with a sneer in his voice.","cn":"“那你是谁？”他的声音中带着冷笑。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"讥笑;嘲笑;讥讽","en":"If you sneer at someone or something, you express your contempt for them by the expression on your face or by what you say.","ex":{"en":"There is too great a readiness to sneer at anything the Opposition does","cn":"对反对党的任何举动都想加以嘲笑的心理过于急切了。"}}]},"media":{"uk":"media/uk/sneer__gb_1.mp3","us":"media/us/sneer__us_1.mp3"},"examples":[{"en":"A faint sneer of satisfaction crossed her face.","cn":"她的脸上掠过一丝得意的冷笑。"},{"en":"‘You? A writer?’ she sneered. “","cn":"你？是作家？”她不屑地说。"}]},"snack":{"oxford":{"phon":"snæk","pos":"noun","senses":[{"en":"a small meal or amount of food, usually eaten in a hurry","cn":"点心；小吃；快餐","lab":"informal","ex":{"en":"a mid-morning snack","cn":"上午十点左右吃的点心"}},{"en":"a thing that is easy to do","cn":"易办到的事；小菜一碟","lab":"Australian English, informal，，","ex":{"en":"It'll be a snack.","cn":"这不过是小事一桩。"}},{"en":"to eat snacks between or instead of main meals","cn":"吃点心（或快餐、小吃）","ex":{"en":"If you snack between meals, try to avoid sugary foods like chocolate.","cn":"如果你在两餐之间吃点心，尽量避开巧克力之类的含糖食品。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"快餐;便餐","en":"A snack is a simple meal that is quick to cook and to eat.","ex":{"en":"Lunch was a snack in the fields.","cn":"午饭是在野外吃的便餐。"}},{"pos":"N-COUNT 可数名词","cn":"小吃;零嘴","en":"A snack is something such as a chocolate bar that you eat between meals.","ex":{"en":"Do you eat sweets, cakes or sugary snacks?","cn":"你吃糖果、蛋糕或甜点吗？"}},{"pos":"VERB 动词","cn":"吃小吃;吃点心","en":"If you snack, you eat snacks between meals.","ex":{"en":"Instead of snacking on crisps and chocolate, nibble on celery or carrot","cn":"不要把薯片和巧克力当零食来吃，要吃些芹菜和胡萝卜。"}}]},"media":{"uk":"media/uk/snack__gb_1.mp3","us":"media/us/snack__us_1.mp3"},"examples":[{"en":"It's healthier to snack on fruit rather than chocolate.","cn":"作为点心，水果比巧克力更有益于健康。"},{"en":"I only have time for a snack at lunchtime.","cn":"中午，我的时间只够吃点心。"}]},"snowman":{"media":{"uk":"media/uk/snowman__gb_1.mp3","us":"media/us/snowman__us_1.mp3"},"oxford":{"phon":"ˈsnəʊmæn","pos":"noun","senses":[{"en":"a figure like a person that people, especially children, make out of snow for fun","cn":"雪人","ex":{"en":"to make/build a snowman","cn":"堆雪人"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"雪人","en":"A snowman is a large shape which is made out of snow, especially by children, and is supposed to look like a person."}]}},"snow-white":{"oxford":{"phon":"ˌsnəʊ ˈwaɪt","pos":"","senses":[{"en":"a traditional children's story. Snow White is a beautiful princess. Her stepmother (= the woman who married her father after her mother died) is jealous of her beauty and orders a man to kill her. He feels pity for her and leaves her alive in a forest, where she lives happily with seven dwarfs (= very small people). The stepmother discovers that Snow White is alive, and gives her an apple full of poison. Snow White falls asleep after eating it and does not wake up until a prince kisses her, and all ends happily. The story was made into a successful Walt Disney film in 1937, and is a popular subject for pantomimes in Britain. In the film the seven dwarfs are called Dopey, Doc, Sneezy, Bashful, Sleepy, Grumpy and Happy.","cn":"白雪公主：一个传统的儿童故事。白雪公主是一位美丽的公主。她的继母（母亲去世后嫁给父亲的女人）嫉妒她的美丽，并命令男人杀死她。他对她感到同情，并让她活在森林中，在那里她与七个小矮人（非常小的人）一起快乐地生活。继母发现白雪公主还活着，并给了她一个充满毒药的苹果。白雪公主吃完它就睡着了，直到王子亲了她才醒来，一切都幸福地结束了。这个故事在1937年被成功地制作成迪斯尼电影，在英国哑剧中很受欢迎。在这部电影中，七个小矮人分别叫“ Dopey”，“ Doc”，“ Sneezy”，“ Bashful”，“ Sleepy”，“脾气暴躁”和“ Happy”。"},{"en":"pure white in colour","cn":"雪白的","ex":{"en":"snow-white sheets","cn":"雪白的床单"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"雪白的","en":"Something that is snow-white is of a bright white colour.","ex":{"en":"His hair was snow white like an old man's.","cn":"他的头发像老年人的头发一样，雪白雪白的。"}}]},"media":{"uk":"media/uk/snow_white_1_gb_1.mp3","us":"media/us/snow_white_1_us_1.mp3"},"examples":[{"en":"snow-white sheets","cn":"雪白的床单"}]},"snowfall":{"media":{"uk":"media/uk/snowfall__gb_1.mp3","us":"media/us/snowfall__us_1.mp3"},"oxford":{"phon":"ˈsnəʊfɔːl","pos":"noun","senses":[{"en":"an occasion when snow falls; the amount of snow that falls in a particular place in a period of time","cn":"下雪；降雪（量）","ex":{"en":"a heavy/light snowfall","cn":"大雪；小雪"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"降雪量","en":"The snowfall in an area or country is the amount of snow that falls there during a particular period.","ex":{"en":"The total rain and snowfall amounted to 50mm.","cn":"降雨量和降雪量共达 50 毫米。"}},{"pos":"N-COUNT 可数名词","cn":"(一场)降雪","en":"A snowfall is a fall of snow."}]},"examples":[{"en":"What is the average annual snowfall for this state?","cn":"这个国家的年平均降雪量是多少？"},{"en":"an area of low snowfall","cn":"降雪量少的地区"}]},"snow":{"media":{"uk":"media/uk/snow__gb_1.mp3","us":"media/us/snow__us_1.mp3"},"oxford":{"phon":"snəʊ","pos":"noun","senses":[{"en":"small soft white pieces (called flakes) of frozen water that fall from the sky in cold weather; this substance when it is lying on the ground","cn":"雪；雪花；积雪","g":"[uncountable]","lab":"North American English","ex":{"en":"Snow was falling heavily.","cn":"正下着大雪。"}},{"en":"an amount of snow that falls in one particular place or at one particular time","cn":"（某地或某时的）降雪量；一场雪","g":"[plural]","lab":"literary","ex":{"en":"the first snows of winter","cn":"冬天的头几场雪"}},{"en":"when it snows, snow falls from the sky","cn":"下雪","g":"[intransitive]","ex":{"en":"It's been snowing heavily all day.","cn":"大雪下了一整天。"},"pos":"verb"},{"en":"to impress somebody a lot by the things you say, especially if these are not true or not sincere","cn":"（用花言巧语）蒙，唬","g":"[transitive]","lab":"North American English, informal，，","ex":{"en":"He really snowed me with all his talk of buying a Porsche.","cn":"他嘴上老说要买一辆保时捷，还真把我唬住了。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"雪","en":"Snow consists of a lot of soft white bits of frozen water that fall from the sky in cold weather.","ex":{"en":"In Mid-Wales six inches of snow blocked roads","cn":"在威尔士的中部地区，6英寸厚的大雪阻塞了道路。"}},{"pos":"N-PLURAL 复数名词","cn":"降雪;雪季","en":"You can refer to a great deal of snow in an area as the snows .","ex":{"en":"...the first snows of winter","cn":"冬天里的第一场雪"}},{"pos":"VERB 动词","cn":"下雪","en":"When it snows, snow falls from the sky.","ex":{"en":"It had been snowing all night.","cn":"整晚都在下雪。"}},{"pos":"VERB 动词","cn":"用花言巧语鼓动(或迷惑)","en":"If someone snows you, they persuade you to do something or convince you of something by flattering or deceiving you.","ex":{"en":"I'd been a fool letting him snow me with his big ideas.","cn":"我真蠢，居然被他的胡乱吹嘘给蒙蔽了。"}}]},"examples":[{"en":"He really snowed me with all his talk of buying a Porsche.","cn":"他嘴上老说要买一辆保时捷，还真把我唬住了。"},{"en":"20 cm of snow were expected today.","cn":"原来预计今天下 20 厘米厚的雪。"}]},"snowy":{"media":{"uk":"media/uk/snowy__gb_1.mp3","us":"media/us/snowy__us_1.mp3"},"oxford":{"phon":"ˈsnəʊi","pos":"adjective","senses":[{"en":"covered with snow","cn":"被雪覆盖的","g":"[usually before noun]","ex":{"en":"snowy fields","cn":"白雪覆盖的田野"}},{"en":"when a lot of snow falls","cn":"下雪多的","ex":{"en":"a snowy weekend","cn":"大雪纷飞的周末"}},{"en":"very white, like new snow","cn":"雪白的","lab":"literary","ex":{"en":"snowy hair","cn":"白发"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"积雪覆盖的;大雪纷飞的","en":"A snowy place is covered in snow. A snowy day is a day when a lot of snow has fallen.","ex":{"en":"...the snowy peaks of the Bighorn Mountains.","cn":"比格霍恩山白雪皑皑的群峰"}}]},"examples":[{"en":"snowy fields","cn":"白雪覆盖的田野"},{"en":"a snowy weekend","cn":"大雪纷飞的周末"}]},"snowshoe":{"oxford":{"phon":"ˈsnəʊʃuː","pos":"noun","senses":[{"en":"one of a pair of flat frames that you attach to the bottom of your shoes so that you can walk on deep snow without sinking in","cn":"雪鞋（平面框式结构，可固定在鞋底，在深雪中行走时穿）"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"雪鞋","en":"Snowshoes are oval frames which have a strong net stretched across them and which you fasten to your feet so that you can walk on deep snow."}]},"media":{"uk":"media/uk/snowshoe__gb_1.mp3","us":"media/us/snowshoe__us_1.mp3"}},"snow-covered":{"oxford":{"phon":"ˈsnəʊ kʌvəd","pos":"adjective","senses":[{"en":"covered with snow","cn":"被雪覆盖的","ex":{"en":"snow-covered fields","cn":"白雪覆盖的田野"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"被雪覆盖的","en":"Snow-covered places and things are covered over with snow.","ex":{"en":"...a Swiss chalet set in the snow-covered hills.","cn":"雪山里的一座瑞士小木屋"}}]},"media":{"uk":"media/uk/snow_covered_1_gb_1.mp3","us":"media/us/snow_covered_1_us_1.mp3"},"examples":[{"en":"snow-covered fields","cn":"白雪覆盖的田野"}]},"snobbery":{"media":{"uk":"media/uk/snobbery__gb_1.mp3","us":"media/us/snobbery__us_1.mp3"},"oxford":{"phon":"ˈsnɒbəri","pos":"noun","senses":[{"en":"the attitudes and behaviour of people who are snobs","cn":"势利态度（或行为）；自以为优越的态度（或行为）","ex":{"en":"intellectual snobbery","cn":"智力上的自我优越感"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"势利态度;势利眼","en":"Snobbery is the attitude of a snob."}]},"examples":[{"en":"intellectual snobbery","cn":"智力上的自我优越感"}]},"snail":{"media":{"img":["media/ldoce/img/snail.jpg","media/pic/gastropods_comp.jpg"],"uk":"media/uk/snail__gb_1.mp3","us":"media/us/snail__us_1.mp3"},"oxford":{"phon":"sneɪl","pos":"noun","senses":[{"en":"a small, soft creature with a hard, round shell on its back, that moves very slowly and often eats garden plants. Some types of snail can be eaten.","cn":"蜗牛","ex":{"en":"the war with the slugs and snails in my garden","cn":"我与园子里的蛞蝓、蜗牛展开的战斗"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"蜗牛","en":"A snail is a small animal with a long, soft body, no legs, and a spiral-shaped shell. Snails move very slowly."},{"pos":"PHRASE 短语","cn":"慢吞吞地;缓慢地","en":"If you say that someone does something at a snail's pace, you are emphasizing that they are doing it very slowly, usually when you think it would be better if they did it much more quickly.","ex":{"en":"The train was moving now at a snail's pace","cn":"火车这会儿走得跟蜗牛一样慢。"}}]},"examples":[{"en":"Traffic was moving at a snail’s pace.","cn":"车辆移动的速度慢得像蜗牛。"}]},"snap":{"media":{"img":["media/pic/fasteners_clothes_comp.jpg","media/thumb/pressstud.jpg","media/ldoce/img/ldoce_308.png"],"uk":"media/uk/snap__gb_1.mp3","us":"media/us/snap__us_1.mp3"},"oxford":{"phon":"snæp","pos":"verb","senses":[{"en":"to break something suddenly with a sharp noise; to be broken in this way","cn":"（使咔嚓）断裂，绷断","g":"[transitive, intransitive]","sc":"break","ex":{"en":"The wind had snapped the tree in two.","cn":"风把树咔嚓一声刮断了。"}},{"en":"to take a photograph","cn":"拍照；摄影","g":"[transitive, intransitive]","lab":"informal","sc":"take photograph","ex":{"en":"A passing tourist snapped the incident.","cn":"一个过路的游客把这件事拍了下来。"}},{"en":"to move, or to move something, into a particular position quickly, especially with a sudden sharp noise","cn":"（使啪地）打开，关上，移到某位置","g":"[intransitive, transitive]","sc":"open/close/move into position","ex":{"en":"The lid snapped shut.","cn":"盖子啪地合上了。"}},{"en":"to speak or say something in an impatient, usually angry, voice","cn":"厉声说；怒气冲冲地说；不耐烦地说","g":"[transitive, intransitive]","sc":"speak impatiently","ex":{"en":"‘Don't just stand there,’ she snapped.","cn":"“别光站在那儿。”她生气地说。"}},{"en":"to try to bite somebody/something","cn":"咬","g":"[intransitive]","sc":"of animal","ex":{"en":"The dogs snarled and snapped at our heels.","cn":"几条狗边叫边向着我们的脚后跟咬来。"}},{"en":"to suddenly be unable to control your feelings any longer because the situation has become too difficult","cn":"突然失去自制力；一下子无法自持","g":"[intransitive]","sc":"lose control","ex":{"en":"My patience finally snapped.","cn":"我终于忍不住了。"}},{"en":"to fasten a piece of clothing with a snap","cn":"用子母扣扣，用摁扣扣（衣服）","g":"[intransitive, transitive]","lab":"North American English","sc":"fasten clothing"},{"en":"to start play by passing the ball back between your legs","cn":"发球（从两腿之间把球向后传给队友）","g":"[transitive]","lab":"sport","sc":"in American football","ex":{"en":"Time will not be resumed until the ball is snapped on the next play.","cn":"直到下一场比赛开球后，时间才会恢复。"}},{"en":"a sudden sharp noise, especially one made by something closing or breaking","cn":"（尤指关上或断裂的声音）啪嗒声，咔嚓声","g":"[countable]","sc":"sharp noise","ex":{"en":"She closed her purse with a snap.","cn":"她啪嗒一声合上了钱包。"},"pos":"noun"},{"en":"a photograph, especially one taken quickly","cn":"（尤指抢拍的）照片","g":"[countable]","sc":"photograph","ex":{"en":"holiday snaps","cn":"假日拍的照片"},"pos":"noun"},{"en":"a card game in which players take turns to put cards down and try to be the first to call out ‘snap’ when two similar cards are put down together","cn":"“对儿”牌游戏（游戏者轮流下牌，出现相同的牌时要抢先喊“对儿”）","g":"[uncountable]","sc":"card game","pos":"noun"},{"en":"a type of button used for fastening clothes, consisting of two metal or plastic sections that can be pressed together","cn":"摁扣；子母扣","lab":"North American English","sc":"fastener","pos":"noun"},{"en":"made or done quickly and without careful thought or preparation","cn":"匆忙的；仓促的","ex":{"en":"It was a snap decision.","cn":"那是个仓促的决定。"},"pos":"adjective"},{"en":"you say snap! in the card game called ‘Snap’ when two cards that are the same are put down","cn":"（在“对儿”牌游戏中出现同样的牌时喊的）对儿","pos":"exclamation"},{"en":"people say snap! to show that they are surprised when two things are the same","cn":"（对于两件相同事物表示惊讶）真巧","lab":"British English, informal，，","ex":{"en":"Snap! I've just bought curtains exactly like those.","cn":"真是巧了！我刚买了跟那些一模一样的窗帘！"},"pos":"exclamation"}]},"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"(使)咔嚓一声折断;(使)啪的一声绷断","en":"If something snaps or if you snap it, it breaks suddenly, usually with a sharp cracking noise.","ex":{"en":"He shifted his weight and a twig snapped","cn":"他挪了一下身体的重心，一根树枝咔嚓一声断了。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(使)发出吧嗒一声(合上或打开)","en":"If you snap something into a particular position, or if it snaps into that position, it moves quickly into that position, with a sharp sound.","ex":{"en":"He snapped the notebook shut","cn":"他啪的一声合上了笔记本。"}},{"pos":"VERB 动词","cn":"(打拍子、下指示等时)打响指","en":"If you snap your fingers, you make a sharp sound by moving your middle finger quickly across your thumb, for example in order to accompany music or to order someone to do something.","ex":{"en":"She had millions of listeners snapping their fingers to her first single","cn":"百万听众和着她第一首歌的节拍打着响指。"}},{"pos":"VERB 动词","cn":"恶声恶气地说;声色俱厉地说","en":"If someone snaps at you, they speak to you in a sharp, unfriendly way.","ex":{"en":"'Of course I don't know her,' Roger snapped","cn":"罗杰恶声恶气地说：“我当然不认识她。”"}},{"pos":"VERB 动词","cn":"突然精神崩溃;突然失控","en":"If someone snaps, or if something snaps inside them, they suddenly stop being calm and become very angry because the situation has become too tense or too difficult for them.","ex":{"en":"He finally snapped when she prevented their children from visiting him one weekend","cn":"当她不准孩子们在某个周末去看他的时候，他终于控制不住自己了。"}},{"pos":"VERB 动词","cn":"(狗等动物)突然咬，猛咬","en":"If an animal such as a dog snaps at you, it opens and shuts its jaws quickly near you, as if it were going to bite you.","ex":{"en":"His teeth clicked as he snapped at my ankle","cn":"它猛地朝我的脚脖子咬下去，牙齿还咔咔直响。"}},{"pos":"ADJ 形容词","cn":"(决定、行动等)突然的，仓促的，鲁莽的","en":"A snap decision or action is one that is taken suddenly, often without careful thought.","ex":{"en":"I think this is too important for a snap decision","cn":"我认为，这件事非常重要，不能仓促作决定。"}},{"pos":"N-COUNT 可数名词","cn":"照片","en":"A snap is a photograph.","ex":{"en":"...a snap my mother took last year.","cn":"我母亲去年拍的照片"}},{"pos":"VERB 动词","cn":"给…拍照","en":"If you snap someone or something, you take a photograph of them.","ex":{"en":"He was the first ever non-British photographer to be invited to snap a royal.","cn":"他是有史以来第一个应邀为王室成员拍照的非英籍摄影师。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"“捉对儿”(一种简单的扑克牌游戏，参加者轮流亮牌叠成一叠，争取在出现同点数或同人头的两张牌时，先喊snap以赢得整叠牌)","en":"Snap is a simple British card game in which the players take turns to put cards down on a pile, and try to be the first to shout 'snap' when two cards with the same number or picture are put down."},{"pos":"EXCLAM 感叹语","cn":"“哟！”(对两件物品相似之极发出的惊叹)","en":"You can say 'Snap!' as an expression of surprise when you realize that two things are the same or very similar, for example if you meet a friend wearing the same shirt as you."},{"pos":"N-COUNT 可数名词","cn":"同 snap fastener","en":"A snap is the same as a snap fastener ."},{"pos":"","cn":"","en":"相关词组：snap out of snap up"}]},"examples":[{"en":"All the best bargains were snapped up within hours.","cn":"所有最划得来的便宜货几小时之内就被抢购一空了。"},{"en":"When he said that, something snapped inside her.","cn":"听他说到这里，她内心的感情一下子翻腾起来。"}]},"sneak":{"media":{"uk":"media/uk/sneak__gb_1.mp3","us":"media/us/sneak__us_1.mp3"},"oxford":{"phon":"sniːk","pos":"verb","senses":[{"en":"to go somewhere secretly, trying to avoid being seen","cn":"偷偷地走；溜","g":"[intransitive]","ex":{"en":"I sneaked up the stairs.","cn":"我蹑手蹑脚地上了楼。"}},{"en":"to do something or take somebody/something somewhere secretly, often without permission","cn":"偷偷地做；偷带；偷拿","g":"[transitive]","ex":{"en":"We sneaked a look at her diary.","cn":"我们偷偷看了一眼她的日记。"}},{"en":"to secretly take something that is small or unimportant","cn":"偷走，顺走（不重要的或小的东西）","g":"[transitive]","lab":"informal","ex":{"en":"I sneaked a cake when they were out of the room.","cn":"趁他们不在屋里，我偷偷拿了一块蛋糕。"}},{"en":"to tell an adult that another child has done something wrong, especially in order to cause trouble","cn":"（儿童向成人）打小报告，告状","g":"[intransitive]","lab":"old-fashioned, British English, disapproving，，，，","ex":{"en":"Did you sneak on me to the teacher?","cn":"你有没有向老师告我的状？"}},{"en":"a person, especially a child, who tells somebody about something wrong that another person has done","cn":"打小报告的人，告状者（尤指儿童）","pos":"noun"},{"en":"done without any warning","cn":"突然的；出其不意的","ex":{"en":"a sneak attack","cn":"偷袭"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"潜行;偷偷地走","en":"If you sneak somewhere, you go there very quietly on foot, trying to avoid being seen or heard.","ex":{"en":"Sometimes he would sneak out of his house late at night to be with me","cn":"有时候，他会在深夜里偷偷溜出家与我相会。"}},{"pos":"VERB 动词","cn":"偷带;私运","en":"If you sneak something somewhere, you take it there secretly.","ex":{"en":"He smuggled papers out each day, photocopied them, and snuck them back","cn":"他每天都把文件偷偷地带出去复印，然后再偷偷地拿回来。"}},{"pos":"VERB 动词","cn":"偷(看)","en":"If you sneak a look at someone or something, you secretly have a quick look at them.","ex":{"en":"You sneak a look at your watch to see how long you've got to wait.","cn":"你偷偷地望一眼手表，看看要等多长时间。"}},{"pos":"","cn":"","en":"相关词组：sneak up on"}]},"examples":[{"en":"He sneaked up on his sister and shouted ‘Boo!’.","cn":"他偷偷溜到妹妹身边，然后大喊一声“嘿！”"},{"en":"I sneaked a cake when they were out of the room.","cn":"趁他们不在屋里，我偷偷拿了一块蛋糕。"}]},"snobby":{"oxford":{"phon":"ˈsnɒbɪʃ","pos":"adj.","senses":[{"en":"thinking that having a high social class is very important; feeling that you are better than other people because you are more intelligent or like things that many people do not like","cn":"势利的；自命不凡的"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"同 snobbish","en":"Snobby means the same as snobbish ."}]}},"snarling":{"oxford":{"phon":"snɑːl","pos":"verb","senses":[{"en":"to show the teeth and make a deep angry noise in the throat","cn":"龇牙低吼"},{"en":"to speak in an angry or bad-tempered way","cn":"咆哮着说；不耐烦地说"}]}},"snooze":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(尤指在白天的)小睡，打盹儿","en":"A snooze is a short, light sleep, especially during the day."},{"pos":"VERB 动词","cn":"小睡;打盹儿","en":"If you snooze, you sleep lightly for a short period of time.","ex":{"en":"Mark snoozed in front of the television","cn":"马克在电视机前打起盹儿来。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to sleep for a short time during the day","cn":""},{"en":"to sleep lightly for a short time, so that you wake up and go back to sleep again, often while you are sitting in a chair or when you do not intend to","cn":""},{"en":"to sleep for a short time, especially during the day when you do not usually sleep","cn":""}]},"vocab":{"pos":"v n","senses":[{"en":"When you snooze , you take a quick nap during the day. Nobody snoozes for too long though, because then you’d just call it \"sleeping.\""}]},"media":{"uk":"media/ldoce/hwd/bre/4/snooze0205.mp3","us":"media/ldoce/hwd/ame/f/snooze.mp3"},"examples":[{"en":"My brother was snoozing on the sofa.","cn":"我弟弟正在沙发上打盹。"},{"en":"I often have a snooze after lunch.","cn":"我常在午饭后睡个小觉。"}],"oxford":{"phon":"snuːz","pos":"verb","senses":[{"en":"to have a short, light sleep, especially during the day and usually not in bed","cn":"（尤指在白天）小睡，打盹","ex":{"en":"My brother was snoozing on the sofa.","cn":"我弟弟正在沙发上打盹。"}},{"en":"a short, light sleep, especially during the day and usually not in bed","cn":"（尤指白天的）小睡，打盹","g":"[countable, usually singular]","lab":"informal","ex":{"en":"I often have a snooze after lunch.","cn":"我午饭后经常小睡片刻。"},"pos":"noun"},{"en":"a control on a clock or phone that you press when you wake up, so that you can sleep a little longer and be woken up again after a short time","cn":"（闹钟或电话的）小睡催醒按钮，贪睡按钮","g":"[uncountable]","ex":{"en":"I pressed snooze and drifted off again.","cn":"我按完贪睡按钮便又进入了梦乡。"},"pos":"noun"}]}},"snotty":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"流着鼻涕的;满是鼻涕的","en":"Something that is snotty produces or is covered in snot.","ex":{"en":"He suffered from a snotty nose, runny eyes and a slight cough.","cn":"他又是流鼻涕，又是流眼泪，还有点咳嗽。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"傲慢自大的;自以为高人一等的","en":"If you describe someone as snotty, you disapprove of them because they have a very proud and superior attitude to other people.","ex":{"en":"...snotty college kids","cn":"目空一切的大学生"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"someone who thinks that they are better than people from a lower social class","cn":""},{"en":"someone who is snobbish thinks that they are better than people from a lower class, so that they will not be friendly with them or do the things they do","cn":""},{"en":"someone who is stuck-up thinks that they are better than other people, and behaves in a proud, unfriendly way","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/2/snotty0205.mp3","us":"media/ldoce/hwd/ame/a/snotty.mp3"},"examples":[{"en":"a snotty nose","cn":"流着鼻涕的鼻子"},{"en":"snotty kids","cn":"淌着鼻涕的小孩"}],"oxford":{"phon":"ˈsnɒti","pos":"adjective","senses":[{"en":"snooty (= treating people as if they are not as good or as important as you)","cn":"卑鄙的人"},{"en":"full of or covered in snot","cn":"流鼻涕的；满是鼻涕的","ex":{"en":"a snotty nose","cn":"流着鼻涕的鼻子"}}]}},"snare":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(捕鸟或小野兽的)陷阱，罗网","en":"A snare is a trap for catching birds or small animals. It consists of a loop of wire or rope which pulls tight around the animal."},{"pos":"N-COUNT 可数名词","cn":"陷阱;圈套","en":"If you describe a situation as a snare, you mean that it is a trap from which it is difficult to escape.","ex":{"en":"Given data which are free from bias there are further snares to avoid in statistical work","cn":"即使数据本身不存在偏差在统计工作中仍需要避免其他陷阱。"}},{"pos":"VERB 动词","cn":"用陷阱(或罗网)捕捉","en":"If someone snares an animal, they catch it using a snare.","ex":{"en":"He'd snared a rabbit earlier in the day.","cn":"那天早一点的时候，他设套捉了一只兔子。"}},{"pos":"VERB 动词","cn":"诱…入圈套;诱惑","en":"If someone is snared, they are caught in a trap.","ex":{"en":"A motorcyclist was seriously injured when she was snared by a rope stretched across the road.","cn":"一个骑摩托的女子被横扯在马路上的一根绳子给绊倒了，伤势严重。"}},{"pos":"VERB 动词","cn":"谋得;诱获","en":"If someone snares something, they get it in a clever way, perhaps by deceiving people.","ex":{"en":"Most of all I want to snare a husband","cn":"最重要的是，我想钓得一个金龟婿。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a trap for catching an animal, especially one that uses a wire or rope to catch the animal by its foot 〔","cn":"捕捉动物的〕罗网﹐套索﹐陷阱"},{"en":"something that is intended to trick someone and get them into a difficult situation","cn":"圈套﹐骗局﹐陷阱"},{"en":"to catch an animal by using a snare","cn":"设陷阱捕捉〔动物〕"}]},"vocab":{"pos":"1 n v 2 n","senses":[{"en":"A snare is a trap, usually for small animals, and using a noose. Snare can also mean to trap in general or any type of trap, like the snare of a TV cliffhanger that traps you into watching again."}]},"media":{"uk":"media/ldoce/hwd/bre/c/snare_n0205.mp3","us":"media/ldoce/hwd/ame/6/snare1.mp3"},"examples":[{"en":"( figurative ) Her one thought was to snare a rich husband.","cn":"她一心要攀住一个有钱的丈夫。"},{"en":"( figurative ) He found himself snared in a web of intrigue.","cn":"他发现自己中了圈套。"}],"oxford":{"phon":"sneə(r)","pos":"noun","senses":[{"en":"a device used for catching small animals and birds, especially one that holds their leg so that they cannot escape","cn":"（捕鸟、兽的）陷阱，罗网，套子","ex":{"en":"The rabbit’s foot was caught in a snare.","cn":"套索把兔子的脚套住了。"}},{"en":"a situation which seems attractive but is unpleasant and difficult to escape from","cn":"陷阱；圈套；骗局","lab":"formal","ex":{"en":"City life can be full of snares for young people.","cn":"对于年轻人来说，城市生活充满了陷阱。"}},{"en":"the metal strings that are stretched across the bottom of a snare drum","cn":"（绷在小鼓下鼓皮的）响弦"},{"en":"to catch something, especially an animal, in a snare","cn":"设陷阱（或罗网、套子）捕捉","lab":"figurative","ex":{"en":"to snare a rabbit","cn":"套兔子"},"pos":"verb"}]}},"snifter":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"少量烈酒","en":"A snifter is a small amount of an alcoholic drink."},{"pos":"N-COUNT 可数名词","cn":"(盛白兰地用的)小口大肚酒杯","en":"A snifter is a bowl-shaped glass used for drinking brandy."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a special large glass for drinking brandy","cn":"白兰地酒杯"},{"en":"a small amount of an alcoholic drink","cn":"一小杯酒"}]},"media":{"uk":"media/ldoce/hwd/bre/7/ld41snifter.mp3","us":"media/ldoce/hwd/ame/f/snifter.mp3"},"oxford":{"phon":"ˈsnɪftə(r)","pos":"noun","senses":[{"en":"a large glass used for drinking brandy","cn":"白兰地酒杯","lab":"especially North American English"},{"en":"a small amount of a strong alcoholic drink","cn":"少量烈酒","lab":"old-fashioned, British English, informal，，，，"}]}},"sniffy":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"轻蔑的;鄙夷的","en":"Someone who is sniffy about something does not think it is of high quality, perhaps unfairly.","ex":{"en":"Some people are a bit sniffy about television.","cn":"某些人对电视有点嗤之以鼻。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"having a disapproving attitude towards something or someone, especially because you think they are not good enough for you","cn":"瞧不起人的﹐傲慢的"}]},"media":{"uk":"media/ldoce/hwd/bre/7/ld41sniffy.mp3","us":"media/ldoce/hwd/ame/7/ld41sniffy.mp3"},"examples":[{"en":"Well, don’t get sniffy about it!","cn":"好了﹐别这么不屑一顾的样子！"}],"oxford":{"phon":"ˈsnɪfi","pos":"adjective","senses":[{"en":"not approving of something/somebody because you think they are not good enough for you","cn":"（对…）轻视，不屑一顾","ex":{"en":"They were very sniffy about letting us in without jackets.","cn":"他们对我们不穿夹克就让我们进来非常不屑。"}}]}},"snappy":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(说话)生气勃勃的，活泼的，明快的","en":"If someone has a snappy style of speaking, they speak in a quick, clever, brief, and often funny way.","ex":{"en":"Each film gets a snappy two-line summary.","cn":"每部影片都配有简洁明快的双行内容提要。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(穿着)入时的,时髦的","en":"If someone is a snappy dresser or if they wear snappy clothes, they wear smart, stylish clothes.","ex":{"en":"She has already made a name for herself as a snappy dresser.","cn":"她已是一个小有名气的时尚达人。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(说话态度)没好气的，恶声恶气的","en":"If someone is snappy, they speak to people in a sharp, unfriendly manner.","ex":{"en":"He wasn't irritable or snappy or anything, just slightly perplexed.","cn":"他并不是爱发火或爱起急什么的，他只是有点困惑。"}},{"pos":"PHRASE 短语","cn":"(催促别人做事)快一点","en":"If you tell someone to make it snappy, you tell them to do something quickly.","ex":{"en":"Look at the pamphlets, and make it snappy.","cn":"看看手册，动作要快。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a snappy title or phrase is short, clear, and often funny 〔","cn":"标题﹑词语等〕简洁有趣的"},{"en":"quick to react in an angry way","cn":"急躁的，没好气的"},{"en":"used to tell someone to hurry","cn":"快点"}]},"media":{"uk":"media/ldoce/hwd/bre/b/snappy0205.mp3","us":"media/ldoce/hwd/ame/f/snappy.mp3"},"examples":[{"en":"He summarized the speech snappily.","cn":"他对讲话做了精练的摘要。"},{"en":"She's a snappy dresser.","cn":"她衣着入时。"}],"oxford":{"phon":"ˈsnæpi","pos":"adjective","senses":[{"en":"clever or funny and short","cn":"精练的；简洁的","ex":{"en":"a snappy slogan","cn":"精练的口号"}},{"en":"attractive and fashionable","cn":"漂亮而时髦的","g":"[usually before noun]","lab":"informal","ex":{"en":"a snappy outfit","cn":"漂亮的套装"}},{"en":"tending to speak to people in an angry, impatient way","cn":"烦躁的；没好气的","ex":{"en":"Interruptions make her snappy and nervous.","cn":"打扰会让她变得暴躁和紧张。"}},{"en":"lively; quick","cn":"活泼的；敏捷的","ex":{"en":"a snappy tune","cn":"活泼的曲调"}}]}},"snore":{"collins":{"senses":[{"pos":"VERB 动词","cn":"打鼾;打呼噜","en":"When someone who is asleep snores, they make a loud noise each time they breathe.","ex":{"en":"His mouth was open, and he was snoring.","cn":"他张着嘴巴，打着呼噜。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to take air into your lungs and send it out again","cn":""},{"en":"to breathe out slowly and make a noise that shows you are disappointed, tired, relieved etc","cn":""},{"en":"to breathe quickly and noisily through your mouth, because you have been using a lot of effort","cn":""}]},"collocations":{"phrases":["ADV. loudly, noisily | gently, lightly, quietly, softly She was asleep in a chair and snoring gently. | contentedly He began to snore conten","VERB + SNORE begin to, start to"]},"media":{"uk":"media/ldoce/hwd/bre/8/snore0205.mp3","us":"media/ldoce/hwd/ame/2/snore1.mp3"},"examples":[{"en":"I could hear Paul snoring in the next room.","cn":"我听得见保罗在隔壁房间里打呼噜。"},{"en":"She lay awake listening to his snores.","cn":"她没睡着，躺在那儿听他打呼噜。"}],"oxford":{"phon":"snɔː(r)","pos":"verb","senses":[{"en":"to breathe noisily through your nose and mouth while you are asleep","cn":"打鼾；打呼噜","ex":{"en":"I could hear Paul snoring in the next room.","cn":"我听得见保罗在隔壁房间里打呼噜。"}},{"en":"noisy breathing while you are asleep","cn":"呼噜声；鼾声","ex":{"en":"She lay awake listening to his snores.","cn":"她没睡着，躺在那儿听他打呼噜。"},"pos":"noun"}]}},"snorkel":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(潜水者使用的)通气管，水下呼吸管","en":"A snorkel is a tube through which a person swimming just under the surface of the sea can breathe."},{"pos":"VERB 动词","cn":"用通气管潜泳","en":"When someone snorkels, they swim under water using a snorkel.","ex":{"en":"We went snorkelling, and then returned for lunch.","cn":"我们去潜泳了，然后回来吃午饭。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a tube that allows someone who is swimming to breathe air under water 〔","cn":"潜水者的〕呼吸管"},{"en":"when you swim under water using a snorkel","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"When you snorkel , you swim near the surface of the water while wearing a mask, fins, and a snorkel through which you can breathe. People like to snorkel in coral reefs, where they can see all kinds of ocean life."}]},"media":{"img":["media/ldoce/img/divers_mask.jpg"],"uk":"media/ldoce/hwd/bre/7/snorkel0205.mp3","us":"media/ldoce/hwd/ame/9/snorkel.mp3"},"examples":[{"en":"This is the best snorkel at that price.","cn":"这是那个价钱的呼吸管中最好的。"},{"en":"We went snorkeling in Hawaii.","cn":""}],"oxford":{"phon":"ˈsnɔːkl","pos":"noun","senses":[{"en":"a tube that you can breathe air through when you are swimming under the surface of the water","cn":"（浮潜用的）呼吸管"},{"en":"to swim under the surface of the water while breathing air through a tube (= a snorkel)","cn":"呼吸管：在水面下游泳，同时通过导管呼吸空气（呼吸管）","pos":"verb"}]}},"snapdragon":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"金鱼草","en":"A snapdragon is a common garden plant with small colourful flowers that can open and shut like a mouth."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a garden plant with white, red, or yellow flowers","cn":"金鱼草〔一种庭院植物〕"}]},"media":{"uk":"media/ldoce/hwd/bre/8/snapdragon0205.mp3","us":"media/ldoce/hwd/ame/9/snapdragon.mp3"},"oxford":{"phon":"ˈsnæpdræɡən","pos":"noun","senses":[{"en":"a small garden plant with red, white, yellow or pink flowers that open and shut like a mouth when pressed","cn":"金鱼草（庭园植物，花的口部呈唇形）"}]}},"snob":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"势利小人","en":"If you call someone a snob, you disapprove of them because they admire upper-class people and have a low opinion of lower-class people.","ex":{"en":"Going to a private school had made her a snob","cn":"上私立学校后，她变得很势利。"}},{"pos":"N-COUNT 可数名词","cn":"自以为(在智力或品位方面)高人一等的人","en":"If you call someone a snob, you disapprove of them because they behave as if they are superior to other people because of their intelligence or taste.","ex":{"en":"She was an intellectual snob.","cn":"她自以为才智高人一等。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who is snobbish thinks that they are better than people from a lower social class","cn":""},{"en":"someone who thinks that they are better than people from a lower social class, and does not want to talk to them or be friends with them","cn":""},{"en":"proud and unfriendly because you think you are better and more important than other people","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"If your best friend tells you that you've become a snob , he means that you've become condescending and you like to think you're better than everyone else. Of course maybe he's a snob for looking down on your behavior — how annoying!"}]},"media":{"uk":"media/ldoce/hwd/bre/a/snob0205.mp3","us":"media/ldoce/hwd/ame/c/snob.mp3"},"examples":[{"en":"There is a snob value in driving the latest model.","cn":"开最新款式的车能满足一种庸俗的虚荣心。"},{"en":"She's such a snob!","cn":"她就是那么一个势利的人！"}],"oxford":{"phon":"snɒb","pos":"noun","senses":[{"en":"a person who admires people in the higher social classes too much and has no respect for people in the lower social classes","cn":"势利小人；谄上欺下的人","ex":{"en":"She's such a snob!","cn":"她就是那么一个势利的人！"}},{"en":"a person who thinks they are much better than other people because they are intelligent or like things that many people do not like","cn":"自以为优越的人；自命高雅的人","ex":{"en":"an intellectual snob","cn":"自命知识渊博的人"}}]}},"snarl-up":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(交通阻塞等)混乱局面","en":"A snarl-up is a disorganized situation such as a traffic jam, in which things are unable to move or work normally."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a confused situation that prevents work from continuing","cn":"混乱﹐纠缠"},{"en":"a situation in which traffic is prevented from moving","cn":"交通堵塞"}]},"media":{"uk":"media/ldoce/hwd/bre/d/ld41snarl-up.mp3","us":"media/ldoce/hwd/ame/2/snarl-up.mp3"},"examples":[{"en":"There was a big snarl-up on the M1.","cn":"一号高速公路上交通严重堵塞。"}],"oxford":{"phon":"ˈsnɑːl ʌp","pos":"noun","senses":[{"en":"a situation in which traffic is unable to move","cn":"交通阻塞","ex":{"en":"We were caught in the rush-hour snarl-up.","cn":"我们陷入了高峰时段的混乱之中。"}}]}},"snuggle":{"collins":{"senses":[{"pos":"VERB 动词","cn":"(尤指靠近另一人)依偎，舒适地蜷卧","en":"If you snuggle somewhere, you settle yourself into a warm, comfortable position, especially by moving closer to another person.","ex":{"en":"Jane snuggled up against his shoulder","cn":"简依偎着他的肩膀。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to settle into a warm comfortable position 〔","cn":"温暖而舒服地〕依偎﹐蜷伏"}]},"vocab":{"pos":"v n","senses":[{"en":"To snuggle is to cuddle with someone. Snuggling is a little like hugging, and it often takes place in bed."}]},"collocations":{"phrases":["ADV. close She slipped her arm through his and snuggled close. | down, up I snuggled down in my sleeping bag.","PREP. against Claudia snuggled against him. | into She snuggled into him and closed her eyes."]},"media":{"uk":"media/ldoce/hwd/bre/e/snuggle0205.mp3","us":"media/ldoce/hwd/ame/4/snuggle.mp3"},"examples":[{"en":"He snuggled down under the bedclothes.","cn":"他躺下以后盖上被子，很舒服。"},{"en":"She snuggled closer.","cn":"她把身子蜷得更紧些。"}],"oxford":{"phon":"ˈsnʌɡl","pos":"verb","senses":[{"en":"to get into, or to put somebody/something into, a warm comfortable position, especially close to somebody","cn":"（使）依偎，紧贴，蜷伏","ex":{"en":"The child snuggled up to her mother.","cn":"孩子依偎着她的母亲。"}}]}},"snapshot":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"快照;抓拍的照片","en":"A snapshot is a photograph that is taken quickly and casually."},{"pos":"N-COUNT 可数名词","cn":"大致印象;简况","en":"If something provides you with a snapshot of a place or situation, it gives you a brief idea of what that place or situation is like.","ex":{"en":"The interviews present a remarkable snapshot of Britain in these dark days of recession.","cn":"这些访谈生动地展现了英国在黑暗的萧条时期的概貌。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a photograph taken quickly and often not very skilfully","cn":"快照〔通常技巧不高〕"},{"en":"a piece of information that quickly gives you an idea of what the situation is like at a particular time","cn":"简要描述﹐简介"}]},"media":{"uk":"media/ldoce/hwd/bre/4/snapshot0205.mp3","us":"media/ldoce/hwd/ame/6/snapshot.mp3"},"examples":[{"en":"snapshots of the children","cn":"孩子们的照片"},{"en":"The book gives us a snapshot of life in the Middle Ages.","cn":"这本书向我们简要介绍了中世纪的生活。"}],"oxford":{"phon":"ˈsnæpʃɒt","pos":"noun","senses":[{"en":"a photograph, especially one taken quickly","cn":"（尤指抢拍的）照片","ex":{"en":"snapshots of the children","cn":"孩子们的照片"}},{"en":"a short description or a small amount of information that gives you an idea of what something is like","cn":"简介；简要说明","g":"[usually singular]","ex":{"en":"The play offers a snapshot of life in Britain under the Romans.","cn":"该剧描绘了罗马人统治下的英国生活。"}}]}},"sneeringly":{"collins":{"senses":[{"pos":"ADV-GRADED 副词","cn":"讽刺地;讥笑地","en":"To refer sneeringly to someone or something means to refer to them in a way that shows your contempt for them.","ex":{"en":"...those in what the Tories sneeringly call the 'chattering classes'","cn":"被保守党讥讽为“名嘴阶层”的那些人"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to make someone or something seem stupid by making jokes about them","cn":""},{"en":"to make fun of someone or something, especially in an unkind way","cn":""},{"en":"to make jokes about someone when you talk to them, either in an unkind way, or in a friendly way that shows you like them","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/f/sneer_v0205.mp3","us":"media/ldoce/hwd/ame/8/sneer1.mp3"},"examples":[{"en":"‘Is that your best outfit?’ he sneered.","cn":""},{"en":"She sneered at Tom’s musical tastes.","cn":""}],"oxford":{"phon":"ˈsnɪərɪŋli","pos":"adverb","senses":[{"en":"in a way that shows that you have no respect for somebody by the expression on your face or by the way that you speak","cn":"嘲笑；讥讽；嗤笑"}]}},"snowstorm":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"暴风雪","en":"A snowstorm is a very heavy fall of snow, usually when there is also a strong wind blowing at the same time."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a period of very bad weather when there is a lot of rain or snow, strong winds, and often lightning","cn":""},{"en":"a storm in which there is a lot of thunder (= loud noise in the sky ) and lightning (= flashes of light in the sky )","cn":""},{"en":"a storm that has very strong fast winds and that moves over water – used about storms in the North Atlantic Ocean","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/9/snowstorm0205.mp3","us":"media/ldoce/hwd/ame/9/snowstorm.mp3"},"oxford":{"phon":"ˈsnəʊstɔːm","pos":"noun","senses":[{"en":"a very heavy fall of snow, usually with a strong wind","cn":"雪暴；暴风雪","ex":{"en":"It is accepted that exceptional snowstorms can occur without strong winds.","cn":"人们普遍认为，即使没有强风，也可能会发生特殊的暴风雪。"}}]}},"snort":{"collins":{"senses":[{"pos":"VERB 动词","cn":"(人或牲畜)喷鼻息;(人表示不赞成、可笑等)哼鼻子，嗤之以鼻","en":"When people or animals snort, they breathe air noisily out through their noses. People sometimes snort in order to express disapproval or amusement.","ex":{"en":"Harrell snorted with laughter","cn":"哈勒尔扑哧一声笑了。"}},{"pos":"VERB 动词","cn":"(表示轻蔑)哼着鼻子说","en":"If someone snorts something, they say it in a way that shows contempt.","ex":{"en":"'Reports,' he snorted. 'Anyone can write reports.'","cn":"“报告，”他哼着鼻子说，“谁都会写。”"}},{"pos":"VERB 动词","cn":"吸食(毒品)","en":"To snort a drug such as cocaine means to breathe it in quickly through your nose.","ex":{"en":"He died of cardiac arrest after snorting cocaine.","cn":"他死于吸食可卡因之后的心脏停搏。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to breathe in noisily through your nose, for example because you have a cold or because you are crying","cn":""},{"en":"to breathe in and out noisily, because you are disappointed, tired, or sad, or because you can begin to relax after worrying about something","cn":""},{"en":"to suddenly breathe in noisily, because you are surprised, shocked, or in pain","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"A snort is a sound you make by suddenly exhaling through your nose, especially if you're disgusted by something. Your response to your little brother's tempter tantrum might be a disdainful snort ."}]},"collocations":{"phrases":["ADV. loudly | softly | angrily, contemptuously, derisively, impatiently, indignantly He snorted indignantly and walked away.","PREP. in He snorted in disgust. | with Her friends snorted with laughter."]},"media":{"uk":"media/ldoce/hwd/bre/a/snort_v0205.mp3","us":"media/ldoce/hwd/ame/e/snort1.mp3"},"examples":[{"en":"I could hear the snort and stamp of a horse.","cn":"我能听见马打响鼻儿、跺蹄子的声音。"},{"en":"The horse snorted and tossed its head.","cn":"马打了个响鼻儿，晃晃脑袋。"}],"oxford":{"phon":"snɔːt","pos":"verb","senses":[{"en":"to make a loud sound by breathing air out noisily through your nose, especially to show that you are angry or think something is silly","cn":"（尤指表示气愤或认为某事愚蠢）喷鼻息，哼","g":"[intransitive, transitive]","ex":{"en":"The horse snorted and tossed its head.","cn":"马打了个响鼻儿，晃晃脑袋。"}},{"en":"to take drugs by breathing them in through the nose","cn":"用鼻子吸（毒品）","g":"[transitive]","ex":{"en":"to snort cocaine","cn":"吸可卡因"}},{"en":"a loud sound that you make by breathing air out noisily through your nose, especially to show that you are angry or think something is silly","cn":"（尤指表示气愤或认为某事愚蠢的）喷鼻息，哼","ex":{"en":"to give a snort","cn":"哼了一声"},"pos":"noun"},{"en":"a small amount of a drug that is breathed in through the nose; an act of taking a drug in this way","cn":"（用鼻子吸入的）毒品；用鼻子吸毒","ex":{"en":"to take a snort of cocaine","cn":"吸一下可卡因"},"pos":"noun"}]}},"snigger":{"collins":{"senses":[{"pos":"VERB 动词","cn":"暗笑;窃笑","en":"If someone sniggers, they laugh quietly in a disrespectful way, for example at something rude or unkind.","ex":{"en":"Suddenly, three schoolkids sitting near me started sniggering","cn":"3 个坐在我附近的学童突然偷偷地笑了起来。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to make sounds with your voice and move your face, because you think that something is funny","cn":""},{"en":"to laugh quickly in a high voice, especially in a slightly silly way, or because you are nervous or embarrassed","cn":""},{"en":"to laugh quietly, especially because you are thinking about or reading something funny","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/e/snigger0205.mp3","us":"media/ldoce/hwd/ame/1/laadsnigger.mp3"},"examples":[{"en":"What are you sniggering at?","cn":"你偷偷笑什么呢？"},{"en":"What are you sniggering at? This is a serious poem.","cn":"你偷笑什么？这是一首严肃的诗。"}],"oxford":{"phon":"ˈsnɪɡə(r)","pos":"verb","senses":[{"en":"to laugh in a quiet unpleasant way, especially at something rude or at somebody’s problems or mistakes","cn":"窃笑；暗笑","ex":{"en":"What are you sniggering at?","cn":"你偷偷笑什么呢？"}},{"en":"a quiet unpleasant laugh, especially at something rude or at somebody’s problems or mistakes","cn":"窃笑；暗笑","pos":"noun"}]}},"snowbound":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"(人或车)被大雪困住的，因大雪而受阻的","en":"If people or vehicles are snowbound, they cannot go anywhere because of heavy snow.","ex":{"en":"The village became snowbound.","cn":"这个村子被大雪封住了。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"blocked or prevented from leaving a place by large amounts of snow","cn":"被雪困住[封闭]的"}]},"media":{"uk":"media/ldoce/hwd/bre/b/snowbound0205.mp3","us":"media/ldoce/hwd/ame/1/snowbound.mp3"},"examples":[{"en":"travelers who are snowbound at the airport","cn":"被大雪困在机场的旅客"}],"oxford":{"phon":"ˈsnəʊbaʊnd","pos":"adjective","senses":[{"en":"stuck in a particular place and unable to move because a lot of snow has fallen","cn":"被雪困住的","ex":{"en":"The skiers were snowbound in the resort for several days.","cn":"滑雪者们在度假村被雪困了好几天。"}},{"en":"that you cannot use or reach because a lot of snow has fallen","cn":"被雪封住的","ex":{"en":"They were stranded for hours on the snowbound motorway.","cn":"他们在积雪的高速公路上滞留了几个小时。"}}]}},"sniff":{"collins":{"senses":[{"pos":"VERB 动词","cn":"(忍住不哭或表示不赞成时)抽鼻子","en":"When you sniff, you breathe in air through your nose hard enough to make a sound, for example when you are trying not to cry, or in order to show disapproval.","ex":{"en":"She wiped her face and sniffed loudly","cn":"她抹了一把脸，很响地抽着鼻子。"}},{"pos":"VERB 动词","cn":"闻;嗅","en":"If you sniff something or sniff at it, you smell it by sniffing.","ex":{"en":"Suddenly, he stopped and sniffed the air","cn":"他突然停下来，闻了闻空气里的味道。"}},{"pos":"VERB 动词","cn":"嗤之以鼻地表示;轻蔑地说","en":"You can use sniff to indicate that someone says something in a way that shows their disapproval or contempt.","ex":{"en":"'Tourists!' she sniffed.","cn":"她轻蔑地说道：“游客!”"}},{"pos":"VERB 动词","cn":"轻视;蔑视","en":"If you say that something is not to be sniffed at, you think it is very good or worth having. If someone sniffs at something, they do not think it is good enough, or they express their contempt for it.","ex":{"en":"The salary was not to be sniffed at either","cn":"这份工资也不容小觑。"}},{"pos":"VERB 动词","cn":"用鼻子吸入(胶毒等)","en":"If someone sniffs a substance such as glue, they deliberately breathe in the substance or the gases from it as a drug.","ex":{"en":"He felt light-headed, as if he'd sniffed glue.","cn":"他觉得晕乎乎的，好像吸了胶毒一样。"}},{"pos":"N-SING 单数名词","cn":"嗅到;感觉到","en":"If you get a sniff of something, you learn or guess that it might be happening or might be near.","ex":{"en":"You know what they'll be like if they get a sniff of a murder investigation","cn":"你知道如果他们嗅到马上会进行谋杀调查会怎么样。"}},{"pos":"N-SING 单数名词","cn":"一丝;一点儿","en":"If you say that someone has not had a sniff of something, you mean that they have not had even a small chance of getting it.","ex":{"en":"Winterton has never had a sniff of a government job in his entire twenty-one years in parliament.","cn":"在国会的整整21年里，温特顿没有得到过任何在政府里工作的机会。"}},{"pos":"","cn":"","en":"相关词组：sniff around sniff out sniff round"}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to breathe in noisily through your nose, for example because you have a cold or because you are crying","cn":""},{"en":"to breathe in and out noisily, because you are disappointed, tired, or sad, or because you can begin to relax after worrying about something","cn":""},{"en":"to suddenly breathe in noisily, because you are surprised, shocked, or in pain","cn":""}]},"vocab":{"pos":"v n","senses":[{"en":"Smell that cake baking? No? Take a sniff . A sniff is when you take air in through your nose to smell something."}]},"collocations":{"phrases":["ADJ. deep, good | loud","VERB + SNIFF give, let out She gave a loud sniff of disapproval. | hear | get, have, take to get a sniff of fresh air","PREP. between ~s &lsquo;I'm sorry,&rsquo; he said between sniffs. | with a ~ &lsquo;I'm fine,&rsquo; she said with a sniff. | ~ at The dog h","PHRASES a sniff of disapproval • Note at SOUND"]},"media":{"uk":"media/ldoce/hwd/bre/7/sniff_n0205.mp3","us":"media/ldoce/hwd/ame/7/sniff1.mp3"},"examples":[{"en":"They make threats but back down at the first sniff of trouble.","cn":"他们起先气势汹汹，但一看情形不妙立刻软了下来。"},{"en":"‘It's hardly what I'd call elegant,’ she sniffed. “","cn":"要我说，这很难称得上雅致。”她不以为然地说。"}],"oxford":{"phon":"snɪf","pos":"verb","senses":[{"en":"to breathe air in through your nose in a way that makes a sound, especially when you are crying, have a cold, etc.","cn":"抽鼻子（尤指哭泣、患感冒等时出声地用鼻子吸气）","g":"[intransitive]","ex":{"en":"We all had colds and couldn't stop sniffing and sneezing.","cn":"我们都感冒了，一个劲地抽鼻子，打喷嚏。"}},{"en":"to breathe air in through the nose in order to discover or enjoy the smell of something","cn":"（吸着气）嗅，闻","g":"[transitive, intransitive]","ex":{"en":"sniffing the fresh morning air","cn":"吸着早晨的新鲜空气"}},{"en":"to say something in a way that shows that you are annoyed, unhappy or not satisfied or that you do not approve of somebody/something","cn":"抱怨；不以为然地说","g":"[transitive, intransitive]","ex":{"en":"‘It's hardly what I'd call elegant,’ she sniffed.","cn":"“要我说，这很难称得上雅致。”她不以为然地说。"}},{"en":"an act or the sound of sniffing","cn":"吸气（声）；抽鼻子（声）；嗅；闻","g":"[countable]","ex":{"en":"She took a deep sniff of the perfume.","cn":"她使劲闻了闻香水。"},"pos":"noun"},{"en":"an idea of what something is like or that something is going to happen","cn":"感觉；察觉","g":"[singular]","ex":{"en":"The sniff of power went to his head.","cn":"权力在望的感觉使他得意忘形。"},"pos":"noun"},{"en":"a small chance of something","cn":"微小的可能性","g":"[singular]","ex":{"en":"She didn't get even a sniff at a medal.","cn":"她根本不可能拿到奖牌。"},"pos":"noun"}]}},"sneaker":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"运动鞋","en":"Sneakers are casual shoes with rubber soles."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a type of light soft shoe with a rubber sole (= bottom ) , used for sports","cn":"胶底运动鞋"}]},"media":{"uk":"media/ldoce/hwd/bre/b/sneaker0205.mp3","us":"media/ldoce/hwd/ame/4/sneaker.mp3"},"examples":[{"en":"He wore old jeans and a pair of sneakers.","cn":"他穿一条旧牛仔裤，脚蹬运动鞋。"},{"en":"a pair of white sneakers","cn":"一双白色的运动鞋"}],"oxford":{"phon":"ˈsniːkə(r)","pos":"noun","senses":[{"en":"a shoe that you wear for sports or as informal clothing","cn":"运动鞋；便鞋","ex":{"en":"He wore old jeans and a pair of sneakers.","cn":"他穿一条旧牛仔裤，脚蹬运动鞋。"}}]}},"snowdrift":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(被风吹聚成的)雪堆","en":"A snowdrift is a deep pile of snow formed by the wind."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a deep mass of snow formed by the wind 〔","cn":"风吹成的〕雪堆"}]},"media":{"uk":"media/ldoce/hwd/bre/c/snowdrift0205.mp3","us":"media/ldoce/hwd/ame/6/snowdrift.mp3"},"oxford":{"phon":"ˈsnəʊdrɪft","pos":"noun","senses":[{"en":"a deep pile of snow that has been blown together by the wind","cn":"（风吹成的）雪堆","ex":{"en":"The car got stuck in a snowdrift.","cn":"汽车陷在了雪堆里。"}}]}},"snug":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(尤指寒冷天气中)暖烘烘的，温暖舒适的","en":"If you feel snug or are in a snug place, you are very warm and comfortable, especially because you are protected from cold weather.","ex":{"en":"They lay snug and warm amid the blankets.","cn":"他们舒舒服服、暖暖和和地躺在毯子里。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(衣服等)紧身的，贴身的","en":"Something such as a piece of clothing that is snug fits very closely or tightly.","ex":{"en":"...a snug black T-shirt and skin-tight black jeans","cn":"贴身的黑色T恤和紧身的黑色牛仔裤"}},{"pos":"N-COUNT 可数名词","cn":"酒馆内的雅间","en":"A snug is a small room in a pub."}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"making you feel physically relaxed, and not too hard, hot, cold etc. Also used about people feeling physically relaxed","cn":""},{"en":"comfortable – used especially about furniture and clothes","cn":""},{"en":"comfortable and warm – used especially about small rooms, houses etc","cn":""}]},"vocab":{"pos":"adj n","senses":[{"en":"You may have noticed your pants getting a little snug during the holiday season. That could mean they’re just extra comfortable or it could be another way of saying they're feeling a little tight."}]},"media":{"uk":"media/ldoce/hwd/bre/4/snug_adj0205.mp3","us":"media/ldoce/hwd/ame/6/snug.mp3"},"examples":[{"en":"The elastic at the waist gives a nice snug fit.","cn":"腰间的松紧带使衣服正好紧紧贴在身上。"},{"en":"I left the children tucked up snugly in bed.","cn":"我给孩子们掖好被子，让他们睡得暖和。"}],"oxford":{"phon":"snʌɡ","pos":"adjective","senses":[{"en":"warm, comfortable and protected, especially from the cold","cn":"温暖舒适的；保暖的","ex":{"en":"a snug little house","cn":"温暖舒适的小房子"}},{"en":"fitting somebody/something closely","cn":"贴身的；紧身的；严密的；严实的","ex":{"en":"The elastic at the waist gives a nice snug fit.","cn":"腰间的松紧带使衣服正好紧紧贴在身上。"}},{"en":"a small comfortable room in a pub, with seats for only a few people","cn":"（酒吧里的）包间，雅座","pos":"noun"}]}},"snog":{"collins":{"senses":[{"pos":"V-RECIP 相互动词","cn":"(长时间地)拥抱接吻","en":"If one person snogs another, they kiss and hold that person for a period of time. You can also say that two people are snogging .","ex":{"en":"I'm 15 and I've never snogged a girl","cn":"我 15 岁了，还没有亲过一个女孩。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if two people, especially young people, snog , they kiss each other for a long time in a sexual way - used especially humorously","cn":""},{"en":"if two people, especially young people, are necking , they are kissing and touching each other in a sexual way","cn":""},{"en":"if two people are smooching , they are kissing and holding each other in a romantic way","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"To snog is to kiss. A teenage couple might snog throughout an entire two hour movie."}]},"media":{"uk":"media/ldoce/hwd/bre/8/ld41snog.mp3","us":"media/ldoce/hwd/ame/8/ld41snog.mp3"},"examples":[{"en":"I caught him snogging my friend.","cn":"我撞见他正在吻我的朋友。"},{"en":"They were snogging on the sofa.","cn":"他们正在沙发上接吻。"}],"oxford":{"phon":"snɒɡ","pos":"verb","senses":[{"en":"to kiss each other, especially for a long time","cn":"（尤指长时间地）接吻","ex":{"en":"They were snogging on the sofa.","cn":"他们正在沙发上接吻。"}},{"en":"the act of kissing somebody, especially for a long time","cn":"（尤指长时间地）接吻","pos":"noun"}]}},"snitch":{"collins":{"senses":[{"pos":"VERB 动词","cn":"(向当权者)告发，告密","en":"To snitch on a person means to tell someone in authority that the person has done something bad or wrong.","ex":{"en":"She felt like a fifth-grader who had snitched on a classmate.","cn":"她觉得自己就像一个告发了同班同学的五年级学生。"}},{"pos":"N-COUNT 可数名词","cn":"告密者;告发者","en":"A snitch is a person who snitches on other people."},{"pos":"VERB 动词","cn":"偷窃","en":"If you snitch something, you steal it quickly and quietly.","ex":{"en":"Before I'd finished reading it, she snitched my copy of To Kill a Mockingbird.","cn":"我还没有读完我那本《杀死一只知更鸟》，她就把书给偷走了。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to take something that does not belong to you without the owner's permission in a dishonest or illegal way","cn":""},{"en":"to steal something, especially money or things that can be carried away","cn":""},{"en":"to steal something","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/6/ld41snitch2.mp3","us":"media/ldoce/hwd/ame/e/snitch.mp3"},"examples":[{"en":"You little snitch! I'll never tell you anything again!","cn":"你这家伙就爱告密！以后我什么话都不跟你说了！"},{"en":"Johnnie snitched on me to his mom.","cn":"约翰尼在他妈妈那儿告了我的状。"}],"oxford":{"phon":"snɪtʃ","pos":"verb","senses":[{"en":"to tell a parent, teacher, etc. about something wrong that another child has done","cn":"（向家长、教师等）告发，告密，告状","ex":{"en":"Johnnie snitched on me to his mom.","cn":"约翰尼在他妈妈那儿告了我的状。"}},{"en":"a person, especially a child, who tells a parent, teacher, etc. about something wrong that another child has done","cn":"（向家长、教师等）告发，告密，告状","ex":{"en":"You little snitch! I'll never tell you anything again!","cn":"你这个打小报告的家伙，我以后什么都不会告诉你了！"},"pos":"noun"}]}},"sneaky":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"秘密的;鬼祟的;偷偷摸摸的","en":"If you describe someone as sneaky, you disapprove of them because they do things secretly rather than openly.","ex":{"en":"It is a sneaky and underhand way of doing business","cn":"这种做生意的方式偷偷摸摸，遮遮掩掩。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"behaving in a way that is intended to deceive people, for example by lying, cheating, or stealing","cn":""},{"en":"using your power in a dishonest way for your own advantage – used about people in official positions","cn":""},{"en":"good at secretly thinking of clever plans to trick people in order to get what you want","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/a/sneaky0205.mp3","us":"media/ldoce/hwd/ame/7/sneaky.mp3"},"examples":[{"en":"That was a sneaky trick!","cn":"这种把戏可不够光明正大！"},{"en":"a sneaky little trick","cn":"鬼鬼祟祟的小把戏"}],"oxford":{"phon":"ˈsniːki","pos":"adjective","senses":[{"en":"behaving in a secret and sometimes dishonest or unpleasant way","cn":"悄悄的；偷偷摸摸的；鬼鬼祟祟的","ex":{"en":"I took a sneaky glance at my watch.","cn":"我悄悄瞥了一下我的手表。"}}]}},"snowplough":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"雪犁;扫雪机","en":"A snowplough is a vehicle which is used to push snow off roads or railway lines."}]},"oxford":{"phon":"ˈsnəʊplaʊ","pos":"noun","senses":[{"en":"a vehicle or machine for cleaning snow from roads or railways","cn":"雪犁，扫雪机（用以清除公路或铁路上的积雪）"},{"en":"to bring the two points of your skis together, in order to go slower or stop","cn":"（滑雪时）犁式制动，犁式滑降","pos":"verb"}]}},"snowflake":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"雪花","en":"A snowflake is one of the soft, white bits of frozen water that fall as snow."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a small soft flat piece of frozen water that falls as snow","cn":"雪片﹐雪花"}]},"collocations":{"phrases":["SNOWFLAKE + VERB fall, flutter | melt"]},"media":{"uk":"media/ldoce/hwd/bre/e/snowflake0205.mp3","us":"media/ldoce/hwd/ame/5/snowflake.mp3"},"oxford":{"phon":"ˈsnəʊfleɪk","pos":"noun","senses":[{"en":"a small soft piece of frozen water that falls from the sky as snow","cn":"雪花；雪片","ex":{"en":"A single snowflake landed on her nose.","cn":"一片雪花落在她的鼻子上。"}},{"en":"an offensive word for a person who you think expects special treatment or is too sensitive to criticism and easily upset","cn":"（含冒犯义）雪片人，“玻璃心”（指要求特殊对待或敏感脆弱的人）","lab":"informal, disapproving，，"}]}},"snout":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(猪等的)长鼻，口鼻部","en":"The snout of an animal such as a pig is its long nose.","ex":{"en":"Two alligators rest their snouts on the water's surface.","cn":"两只鳄鱼的大嘴栖息在水面上。"}},{"pos":"N-COUNT 可数名词","cn":"口吻状物(如车头、枪管等)","en":"Writers sometimes refer to the front of a car or the barrel of a gun as its snout .","ex":{"en":"The snout of the Mercedes poked through the gates","cn":"奔驰轿车的前部把大门洞穿了。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the long nose of some kinds of animals, such as pigs 〔","cn":"猪等动物的〕口鼻部﹐长鼻子"},{"en":"a criminal who gives information about other criminals to the police","cn":"向警方告发其同伙的罪犯"}]},"vocab":{"pos":"n","senses":[{"en":"An animal's long, protruding nose is often called a snout . The tricky part, though, is that not all long animal noses are called snouts ."}]},"media":{"uk":"media/ldoce/hwd/bre/2/snout0205.mp3","us":"media/ldoce/hwd/ame/a/snout.mp3","img":["media/thumb/snout.jpg"]},"examples":[{"en":"the snout of a pistol","cn":"手枪枪管"}],"oxford":{"phon":"snaʊt","pos":"noun","senses":[{"en":"the long nose and area around the mouth of some types of animal, such as a pig","cn":"（猪等动物的）口鼻部，吻"},{"en":"a person’s nose","cn":"（人的）鼻子","lab":"informal, humorous，，"},{"en":"a part of something that sticks out at the front","cn":"吻状突出物","ex":{"en":"the snout of a pistol","cn":"手枪枪管"}}]}},"snivel":{"collins":{"senses":[{"pos":"VERB 动词","cn":"(令人讨厌地)啜泣，抽抽噎噎地哭，抽鼻子","en":"If someone is snivelling, they are crying or sniffing in a way that irritates you.","ex":{"en":"Billy started to snivel. His mother smacked his hand.","cn":"比利抽抽搭搭地哭了起来。妈妈在他的手上打了一下。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if you cry , tears come from your eyes, for example because you are sad or upset, or because you have hurt yourself","cn":""},{"en":"to cry quietly and for a long time because you are very sad or you feel a strong emotion","cn":""},{"en":"if you sob , you cry noisily and your body shakes, because you are very sad or because someone has upset you","cn":""}]},"vocab":{"pos":"v n","senses":[{"en":"Sometimes, when you really want something, you might resort to whining and blubbering to get it — in other words, you'll snivel . It's never pretty, so try to keep your dignity, and don't snivel !"}]},"media":{"uk":"media/ldoce/hwd/bre/6/snivel0205.mp3","us":"media/ldoce/hwd/ame/9/snivel.mp3"},"examples":[{"en":"A small boy was sniveling on a chair.","cn":"一个小男孩在椅子上抽泣。"},{"en":"a snivelling coward","cn":"一个哭哭啼啼的胆小鬼"}],"oxford":{"phon":"ˈsnɪvl","pos":"verb","senses":[{"en":"to cry and complain in a way that people think is annoying","cn":"（令人讨厌地）哭诉","ex":{"en":"Stop snivelling! I can’t stand it.","cn":"别哭诉了！我受不了。"}}]}},"snoop":{"collins":{"senses":[{"pos":"VERB 动词","cn":"窥探;刺探;打探","en":"If someone snoops around a place, they secretly look around it in order to find out things.","ex":{"en":"Ricardo was the one she'd seen snooping around Kim's hotel room.","cn":"她看见在金的宾馆房间周围窥探的那个人正是里卡多。"}},{"pos":"VERB 动词","cn":"窥探(某人的生活)","en":"If someone snoops on a person, they watch them secretly in order to find out things about their life.","ex":{"en":"Governments have been known to snoop on innocent citizens.","cn":"有些政府窥探无辜公民的生活——这一事实已经众所周知。"}},{"pos":"N-COUNT 可数名词","cn":"同 snooper","en":"A snoop is the same as a snooper .","ex":{"en":"Each neighborhood had its own organization of snoops who reported strangers to the authorities.","cn":"每个居民区都有自己的侦探组织，他们向当局汇报陌生人的情况。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to try to find out about someone's private affairs, especially by secretly looking in their house, examining their possessions etc","cn":""},{"en":"to try to find out about someone's private life by asking a lot of personal questions in a way that people find rude or annoying","cn":""},{"en":"to look around a place, especially someone's home or office, to try to find out things that do not really concern you","cn":""}]},"vocab":{"pos":"v n","senses":[{"en":"When you snoop , you poke around in someone else's business. A teenager might snoop in her sister's room, looking for her diary."}]},"media":{"uk":"media/ldoce/hwd/bre/2/snoop0205.mp3","us":"media/ldoce/hwd/ame/1/snoop1.mp3"},"examples":[{"en":"Someone's been snooping around my apartment.","cn":"有个人一直在我住所周围窥探。"},{"en":"He had a snoop around her office.","cn":"他在她的办公室周围窥探一番。"}],"oxford":{"phon":"snuːp","pos":"verb","senses":[{"en":"to find out private things about somebody, especially by looking secretly around a place","cn":"窥探；打探；探听","ex":{"en":"Someone's been snooping around my apartment.","cn":"有个人一直在我住所周围窥探。"}},{"en":"a person who looks around a place secretly to find out private things about somebody","cn":"窥探者；打探他人私事的人","g":"[countable]","pos":"noun"},{"en":"a secret look around a place","cn":"窥探","g":"[singular]","ex":{"en":"He had a snoop around her office.","cn":"他在她的办公室周围窥探一番。"},"pos":"noun"}]}},"snuff":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"鼻烟","en":"Snuff is powdered tobacco which people take by breathing it in quickly through their nose."},{"pos":"VERB 动词","cn":"断气;死去","en":"If someone snuffs it, they die.","ex":{"en":"He thought he was about to snuff it.","cn":"他觉得自己快要咽气了。"}},{"pos":"","cn":"","en":"相关词组：snuff out"}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to stop a candle burning by pressing the burning part with your fingers or by covering it","cn":"掐灭﹐闷熄〔蜡烛〕"},{"en":"to die","cn":"咽下最后一口气﹐死"},{"en":"if an animal snuffs, it breathes air into its nose in a noisy way, especially in order to smell something 〔","cn":"动物〕大声地嗅﹐闻〔味〕"}]},"collocations":{"phrases":["QUANT. pinch","VERB + SNUFF inhale, take","SNUFF + NOUN box"]},"media":{"uk":"media/ldoce/hwd/bre/8/snuff_v0205.mp3","us":"media/ldoce/hwd/ame/5/snuff1.mp3"},"examples":[{"en":"An innocent child's life has been snuffed out by this senseless shooting.","cn":"这胡乱一枪就要了一个无辜孩子的命。"},{"en":"The dogs were snuffing gently at my feet.","cn":"几只狗轻轻地嗅着我的脚。"}],"oxford":{"phon":"snʌf","pos":"verb","senses":[{"en":"to stop a small flame from burning, especially by pressing it between your fingers or covering it with something","cn":"掐灭，闷熄，熄灭（小火苗）","g":"[transitive]"},{"en":"to smell something by breathing in noisily through the nose","cn":"出声地嗅","g":"[intransitive, transitive]","ex":{"en":"The dogs were snuffing gently at my feet.","cn":"几只狗轻轻地嗅着我的脚。"}},{"en":"tobacco in the form of a powder that people take by breathing it into their noses","cn":"鼻烟","pos":"noun"}]}},"snooker":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"斯诺克","en":"Snooker is a game involving balls on a large table. The players use a long stick to hit a white ball, and score points by knocking coloured balls into the pockets at the sides of the table.","ex":{"en":"...a game of snooker","cn":"一局斯诺克比赛"}},{"pos":"VERB 动词","cn":"阻止…采取行动;使…不如愿","en":"If you are snookered by something, it is difficult or impossible for you to take action or do what you want to do.","ex":{"en":"The President has been snookered on this issue.","cn":"在这个问题上，总统未能如愿。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a game played especially in Britain on a special table covered in green cloth, in which two people use long sticks to hit coloured balls into holes at the sides and corners of the table","cn":"斯诺克台球"},{"en":"→ billiards snooker table/room/hall They meet up every Friday to play snooker .","cn":"他们每周五碰头打斯诺克台球。"},{"en":"to make it impossible for someone to do what they want to do","cn":"使受阻；使落空"}]},"collocations":{"phrases":["ADJ. professional","QUANT. frame, game We played a couple of frames of snooker in the evening.","VERB + SNOOKER play","SNOOKER + NOUN ball, cue, table | ace, champion, player, star | club, hall, room | match, tournament | league •"]},"media":{"uk":"media/ldoce/hwd/bre/c/snooker_n0205.mp3","us":"media/ldoce/hwd/ame/4/amelasdesnooker.mp3"},"examples":[{"en":"Any plans I'd had for the weekend were by now well and truly snookered.","cn":"我原先设想的各项周末计划，这时候就彻底落空了。"},{"en":"a snooker hall/player/table, etc.","cn":"斯诺克厅、斯诺克运动员、斯诺克球桌等"}],"oxford":{"phon":"ˈsnuːkə(r)","pos":"noun","senses":[{"en":"a game for two people played on a long table covered with green cloth. Players use cues (= long sticks) to hit a white ball against other balls (15 red and 6 of other colours) in order to get the coloured balls into pockets at the edge of the table, in a particular set order.","cn":"斯诺克（供两人打的落袋台球，打球人用球杆击打白色母球，按一定顺序撞 15 个红球和 6 个彩球入袋）","g":"[uncountable]","ex":{"en":"to play snooker","cn":"打斯诺克"}},{"en":"a position in snooker in which one player has made it very difficult for the opponent to play a shot within the rules","cn":"（斯诺克比赛中的）障碍球","g":"[countable]"},{"en":"to have your opponent in a snooker","cn":"设障碍球","pos":"verb"},{"en":"to make it impossible for somebody to do something, especially something they want to do","cn":"阻挠；使落空","lab":"British English, informal，，","ex":{"en":"Any plans I'd had for the weekend were by now well and truly snookered.","cn":"我原先设想的各项周末计划，这时候就彻底落空了。"},"pos":"verb"},{"en":"to cheat or trick somebody","cn":"欺骗；使上当","lab":"North American English, informal，，","pos":"verb"}]}},"snub":{"collins":{"senses":[{"pos":"VERB 动词","cn":"冷落;怠慢;不理睬","en":"If you snub someone, you deliberately insult them by ignoring them or by behaving or speaking rudely towards them.","ex":{"en":"He snubbed her in public and made her feel an idiot","cn":"他当众冷落她，让她觉得自己像一个白痴似的。"}},{"pos":"N-COUNT 可数名词","cn":"冷落;怠慢","en":"If you snub someone, your behaviour or your remarks can be referred to as a snub .","ex":{"en":"Ryan took it as a snub","cn":"瑞安觉得这是一种怠慢。"}},{"pos":"ADJ 形容词","cn":"(鼻子)短而略向上翘的","en":"Someone who has a snub nose has a short nose which points slightly upwards."}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to pretend not to notice someone that you know, even though you are looking directly at them","cn":""},{"en":"to ignore someone deliberately, in order to show that you are angry with them or that you have no respect for them","cn":""},{"en":"to completely ignore someone when you see them, especially because you are angry with them","cn":""}]},"vocab":{"pos":"v n adj","senses":[{"en":"To snub is to ignore or refuse to acknowledge someone. If you want to snub your former best friend, you can refuse to even look at her when you pass in the hallway."}]},"collocations":{"phrases":["ADV. deliberately | publicly | rudely","PHRASES feel snubbed He was not invited to the party, and felt snubbed."]},"media":{"uk":"media/ldoce/hwd/bre/4/snub_v0205.mp3","us":"media/ldoce/hwd/ame/6/snub1.mp3"},"examples":[{"en":"Her refusal to attend the dinner is being seen as a deliberate snub to the President.","cn":"在人们看来，她拒不出席宴会是有意让总统难堪。"},{"en":"All the country's leading players snubbed the tournament.","cn":"全国的顶尖运动员都抵制那次比赛。"}],"oxford":{"phon":"snʌb","pos":"verb","senses":[{"en":"to show a lack of respect for somebody, especially by ignoring them when you meet","cn":"冷落；怠慢","ex":{"en":"I tried to be friendly, but she snubbed me completely.","cn":"我尽量和气，但她根本不答理我。"}},{"en":"to refuse to attend or accept something, for example as a protest","cn":"拒不出席；拒不接受；抵制","ex":{"en":"All the country's leading players snubbed the tournament.","cn":"全国的顶尖运动员都抵制那次比赛。"}},{"en":"an action or a comment that is deliberately rude in order to show somebody that you do not like or respect them","cn":"冷落；怠慢的言辞（或行为）","ex":{"en":"Her refusal to attend the dinner is being seen as a deliberate snub to the president.","cn":"在人们看来，她拒不出席宴会是有意让总统难堪。"},"pos":"noun"},{"en":"short, flat and turned up at the end","cn":"短平而上翘的","pos":"adjective"}]}},"snuffle":{"collins":{"senses":[{"pos":"VERB 动词","cn":"(因伤风等)抽鼻子","en":"If a person or an animal snuffles, they breathe in noisily through their nose, for example because they have a cold.","ex":{"en":"She snuffled and wiped her nose on the back of her hand.","cn":"她抽了抽鼻子并用手背擦了擦。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to breathe noisily through your nose, sometimes because you are crying","cn":"呼哧呼哧地呼吸﹐抽鼻子"}]},"media":{"uk":"media/ldoce/hwd/bre/2/snuffle0205.mp3","us":"media/ldoce/hwd/ame/f/snuffle.mp3"},"examples":[{"en":"The silence was broken only by the snuffles of the dogs.","cn":"除了不时听见狗喘气的声音，四下里一片寂静。"},{"en":"I could hear the child snuffling in her sleep.","cn":"我听见这女孩睡着了还在抽鼻子。"}],"oxford":{"phon":"ˈsnʌfl","pos":"verb","senses":[{"en":"to breathe noisily because you have a cold or you are crying","cn":"（因感冒或哭泣）鼻子呼哧出声，抽鼻子","g":"[intransitive, transitive]","ex":{"en":"I could hear the child snuffling in her sleep.","cn":"我听见这女孩睡着了还在抽鼻子。"}},{"en":"if an animal snuffles, it breathes noisily through its nose, especially while it is smelling something","cn":"哧哧地嗅","g":"[intransitive]","ex":{"en":"The dog was snuffling around in the bushes.","cn":"那只狗在灌木丛里嗅来嗅去。"}},{"en":"an act or the sound of snuffling","cn":"抽鼻子（声）；嗅；嗅东西时发出的呼哧声","ex":{"en":"The silence was broken only by the snuffles of the dogs.","cn":"除了不时听见狗喘气的声音，四下里一片寂静。"},"pos":"noun"}]}},"snaffle":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(马的)嚼子;马衔铁","en":"A snaffle is an object consisting of two short joined bars of metal that is put in a horse's mouth and attached to the straps that the rider uses to control the horse."},{"pos":"VERB 动词","cn":"偷窃;扒取;攫取","en":"If you snaffle something, you take it for yourself.","ex":{"en":"Michael Stich then proceeded to snaffle the $2 million first prize.","cn":"接着，迈克尔·斯蒂克又一举拿下了两百万美元的头奖。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to take something quickly, especially before anyone else has had the time or the chance to do this","cn":"攫取﹐抓取﹐〔尤指〕抢到"}]},"media":{"uk":"media/ldoce/hwd/bre/d/ld41snaffle.mp3","us":"media/ldoce/hwd/ame/d/ld41snaffle.mp3"},"examples":[{"en":"I managed to snaffle a couple of biscuits.","cn":"我抢到了几块饼干。"}],"oxford":{"phon":"ˈsnæfl","pos":"verb","senses":[{"en":"to take something quickly for yourself, especially before anyone else has had the time or opportunity","cn":"（尤指抢先）攫取，偷窃"}]}},"snazzy":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"时髦的;漂亮的;新潮的","en":"Something that is snazzy is stylish and attractive, often in a rather bright or noticeable way.","ex":{"en":"...snazzy swimsuits.","cn":"新潮的泳衣"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"wearing good or expensive clothes","cn":""},{"en":"if you look smart or your clothes are smart , you are dressed in an attractive way and you look very tidy","cn":""},{"en":"If you look neat or if you have neat clothes, the clothes you are wearing are clean, ironed, and fit you properly","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/2/ld41snazzy.mp3","us":"media/ldoce/hwd/ame/2/snazzy.mp3"},"examples":[{"en":"a snazzy tie","cn":"漂亮的领带"},{"en":"a snazzy red jacket","cn":"一件鲜艳夺目的红色外套"}],"oxford":{"phon":"ˈsnæzi","pos":"adjective","senses":[{"en":"fashionable, bright and modern, and attracting your attention","cn":"漂亮而时髦的；吸引人的","ex":{"en":"a snazzy tie","cn":"漂亮的领带"}}]}},"snooty":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"傲慢自大的;自以为高人一等的","en":"If you say that someone is snooty, you disapprove of them because they behave as if they are superior to other people.","ex":{"en":"...snooty intellectuals","cn":"妄自尊大的知识分子"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"rude and unfriendly, because you think you are better than other people","cn":"傲慢的﹐目中无人的﹐妄自尊大的"}]},"vocab":{"pos":"adj","senses":[{"en":"Use the word snooty to describe someone who is a terrible, stuck-up snob. Your snooty grandmother might refuse to take the subway because she doesn't want to mix with regular people."}]},"media":{"uk":"media/ldoce/hwd/bre/5/snooty0205.mp3","us":"media/ldoce/hwd/ame/7/snooty.mp3"},"examples":[{"en":"snooty neighbours","cn":"目中无人的邻居"}],"oxford":{"phon":"ˈsnuːti","pos":"adjective","senses":[{"en":"treating people as if they are not as good or as important as you","cn":"傲慢的；目中无人的","ex":{"en":"She was frightfully snooty and superior.","cn":"她非常傲慢和优越。"}}]}},"sniffle":{"collins":{"senses":[{"pos":"VERB 动词","cn":"(哭泣或感冒时)不断抽鼻子","en":"If you sniffle, you keep sniffing, usually because you are crying or have a cold.","ex":{"en":"'Please don't yell at me.' She began to sniffle.","cn":"“请不要对我大喊大叫。”她啜泣起来。"}},{"pos":"N-COUNT 可数名词","cn":"轻微感冒","en":"A sniffle is a slight cold. You can also say that someone has the sniffles ."}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if you cry , tears come from your eyes, for example because you are sad or upset, or because you have hurt yourself","cn":""},{"en":"to cry quietly and for a long time because you are very sad or you feel a strong emotion","cn":""},{"en":"if you sob , you cry noisily and your body shakes, because you are very sad or because someone has upset you","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/c/sniffle_v0205.mp3","us":"media/ldoce/hwd/ame/8/sniffle1.mp3"},"examples":[{"en":"After a while, her sniffles died away.","cn":"过了一会儿，她抽鼻子的声音逐渐平息了。"},{"en":"For goodness’ sake, stop sniffling!","cn":"看在老天爷面上﹐别再抽鼻子了！"}],"oxford":{"phon":"ˈsnɪfl","pos":"verb","senses":[{"en":"to sniff or keep sniffing, especially because you are crying or have a cold","cn":"（尤指因哭泣或患感冒）抽鼻子"},{"en":"an act or the sound of sniffling","cn":"抽鼻子（声）","ex":{"en":"After a while, her sniffles died away.","cn":"过了一会儿，她抽鼻子的声音逐渐平息了。"},"pos":"noun"},{"en":"a slight cold","cn":"轻微感冒","g":"[plural]","ex":{"en":"to get/have the sniffles","cn":"患轻感冒"},"pos":"noun"}]}},"snook":{"collins":{"senses":[{"pos":"PHRASE 短语","cn":"对(权威或机构)进行侮辱(或表示轻蔑)","en":"If you cock a snook at someone in authority or at an organization, you do something that they cannot punish you for, but which insults them or expresses your contempt.","ex":{"en":"Tories cocked a snook at their prime minister over this legislation.","cn":"保守党人就这一法规向他们的首相表示了轻蔑。"}}]},"media":{"uk":"media/ldoce/hwd/bre/c/ld41snook.mp3","us":"media/ldoce/hwd/ame/c/ld41snook.mp3"}},"snarl":{"collins":{"senses":[{"pos":"VERB 动词","cn":"(动物)露齿咆哮，嗥叫","en":"When an animal snarls, it makes a fierce, rough sound in its throat while showing its teeth.","ex":{"en":"He raced ahead up into the bush, barking and snarling","cn":"它嗥叫着冲向前，一头钻进了灌木丛。"}},{"pos":"VERB 动词","cn":"厉声说;吼叫着说;怒气冲冲地说","en":"If you snarl something, you say it in a fierce, angry way.","ex":{"en":"'Let go of me,' he snarled","cn":"他气急败坏地喊道：“放开我。”"}},{"pos":"N-COUNT 可数名词","cn":"混乱的一堆","en":"A snarl is a disorganized mass of things.","ex":{"en":"She was tangled in a snarl of logs and branches.","cn":"她被困在一堆乱七八糟的木料和树枝中间。"}},{"pos":"","cn":"","en":"相关词组：snarl up"}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to say something very quietly, using your breath rather than your full voice","cn":""},{"en":"to say something quietly without pronouncing the words clearly","cn":""},{"en":"to say something quietly, especially when you are annoyed but do not want someone to hear you complaining","cn":""}]},"vocab":{"pos":"1 v n 2 v n","senses":[{"en":"To snarl or make a snarl is to growl like an angry dog or speak abruptly and aggressively. A snarl can also be something tangled or confused."}]},"collocations":{"phrases":["ADV. savagely, viciously He snarled savagely at her. | almost","PREP. at A guard dog snarled at us as we walked by."]},"media":{"uk":"media/ldoce/hwd/bre/1/snarl0205.mp3","us":"media/ldoce/hwd/ame/5/snarl1.mp3"},"examples":[{"en":"The accident snarled up the traffic all day.","cn":"这次事故使交通堵塞了整整一天。"},{"en":"She snarled abuse at anyone who happened to walk past.","cn":"谁碰巧走过，她就冲谁叫骂。"}],"oxford":{"phon":"snɑːl","pos":"verb","senses":[{"en":"to show the teeth and make a deep angry noise in the throat","cn":"龇牙低吼","g":"[intransitive]","ex":{"en":"The dog snarled at us.","cn":"狗朝我们低声吼叫。"}},{"en":"to speak in a rough, low, angry voice","cn":"咆哮着说；不耐烦地说","g":"[transitive, intransitive]","ex":{"en":"‘Get out of here!’ he snarled.","cn":"“滚开！”他吼道。"}},{"en":"a deep sound that an animal makes when it is angry and shows its teeth","cn":"（动物的）龇牙低吼","g":"[usually singular]","ex":{"en":"The dog bared its teeth in a snarl.","cn":"那条狗龇着牙低声吼叫。"},"pos":"noun"},{"en":"an act of speaking in a rough, low, angry voice; the sound you make when you are angry, in pain, etc.","cn":"愤怒叫嚷（声）；咆哮（声）；疼痛叫声","g":"[usually singular]","ex":{"en":"a snarl of hate","cn":"充满仇恨的吼声"},"pos":"noun"},{"en":"something that has become twisted in an untidy way","cn":"缠结物；蓬乱的事物","lab":"informal","ex":{"en":"She used conditioner to remove the snarls from her hair.","cn":"她用护发剂理顺了打结的头发。"},"pos":"noun"},{"en":"a situation in which traffic is unable to move","cn":"交通阻塞","lab":"British English, informal，，","ex":{"en":"rush-hour traffic snarls","cn":"高峰时间的交通阻塞"},"pos":"noun"}]}},"snake":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"蛇","en":"A snake is a long, thin reptile without legs."},{"pos":"VERB 动词","cn":"蜿蜒而行;曲折而行","en":"Something that snakes in a particular direction goes in that direction in a line with a lot of bends.","ex":{"en":"The road snaked through forested mountains","cn":"道路在林间蜿蜒延伸。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an animal with a long thin body and no legs, that often has a poisonous bite","cn":"蛇"},{"en":"someone who cannot be trusted","cn":"阴险小人﹐不可信的人"},{"en":"if a river, road, train, or line snakes somewhere, it moves in long twisting curves （","cn":"使）蜿蜒前进"}]},"collocations":{"phrases":["ADJ. deadly one of the world' s deadliest snakes | poisonous, venomous | grass, sea, tree, water","SNAKE + VERB bite sb/sth, strike sth She was bitten by a snake while walking through long grass. The snake lifted up its head before strikin","SNAKE + NOUN bite (also snakebite) | charmer | venom"]},"media":{"img":["media/ldoce/img/snake.jpg"],"uk":"media/ldoce/hwd/bre/d/brelasdesnake.mp3","us":"media/ldoce/hwd/ame/e/snake1.mp3"},"examples":[{"en":"Venomous snakes spit and hiss when they are cornered.","cn":"毒蛇在无法逃脱时会发出愤怒的呼呼咝咝的声音。"},{"en":"The procession snaked its way through narrow streets.","cn":"队伍沿着狭窄的街道曲折穿行。"}],"oxford":{"phon":"sneɪk","pos":"noun","senses":[{"en":"a reptile with a very long thin body and no legs. There are many types of snake, some of which are poisonous.","cn":"蛇","ex":{"en":"a snake coiled up in the grass","cn":"盘在草丛里的一条蛇"}},{"en":"to move like a snake, in long twisting curves; to go in a particular direction in long twisting curves","cn":"曲折前行；蛇行；蜿蜒伸展","ex":{"en":"The road snaked away into the distance.","cn":"公路蜿蜒伸向远方。"},"pos":"verb"}]}},"snow-capped":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"山顶积雪的","en":"A snow-capped mountain is covered with snow at the top.","ex":{"en":"...the snow-capped Himalayan peaks.","cn":"覆盖着皑皑白雪的喜马拉雅山峰"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"snow-capped mountains are covered in snow at the top 〔","cn":"山〕顶部积雪覆盖的"}]},"media":{"uk":"media/ldoce/hwd/bre/5/ld41snow-capped.mp3","us":"media/ldoce/hwd/ame/c/snow-capped.mp3"},"oxford":{"phon":"ˈsnəʊ kæpt","pos":"adjective","senses":[{"en":"covered with snow on top","cn":"顶部被雪覆盖的"}]}},"snowboarding":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"滑雪板运动","en":"Snowboarding is the sport or activity of travelling down snowy slopes using a snowboard.","ex":{"en":"New snowboarding facilities should attract more people.","cn":"新建的滑雪板运动设施应该会吸引更多的人。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the sport of going down snow-covered hills on a snowboard","cn":"单板滑雪运动"}]},"media":{"uk":"media/ldoce/hwd/bre/a/brelasdesnowboarding.mp3","us":"media/ldoce/hwd/ame/e/laadsnowboarding.mp3","img":["media/thumb/snowboarding.jpg"]},"examples":[{"en":"Snowboarding is now an Olympic sport.","cn":"滑雪板运动现在是奥运会比赛项目。"},{"en":"to go snowboarding","cn":"去进行滑雪板运动"}],"oxford":{"phon":"ˈsnəʊbɔːdɪŋ","pos":"noun","senses":[{"en":"the sport of moving over snow on a snowboard","cn":"单板滑雪；滑雪板运动","ex":{"en":"to go snowboarding","cn":"进行滑雪板运动"}}]}},"sneaking":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"私底下的;暗自的;不敢公开承认的","en":"A sneaking feeling is a slight or vague feeling, especially one that you are unwilling to accept.","ex":{"en":"I have a sneaking suspicion that they are going to succeed","cn":"我隐隐觉得他们恐怕要成功了。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"to think that someone is probably guilty of something illegal or dishonest","cn":""},{"en":"thinking that someone might be guilty of doing something wrong or dishonest, without being sure","cn":""},{"en":"a feeling that someone is probably guilty of doing something wrong or dishonest","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/3/sneaking0205.mp3","us":"media/ldoce/hwd/ame/b/sneaking.mp3"},"examples":[{"en":"I have a sneaking suspicion that she knows more than she's telling us.","cn":"我私下怀疑，她还知道一些情况，不想告诉我们。"},{"en":"She had always had a sneaking affection for him.","cn":"以前她一直暗暗倾心于他。"}],"oxford":{"phon":"ˈsniːkɪŋ","pos":"adjective","senses":[{"en":"if you have a sneaking feeling for somebody or about something, you do not want to admit it to other people, because you feel embarrassed, or you are not sure that this feeling is right","cn":"（指不愿公开的感觉）暗中的，私下的","ex":{"en":"She had always had a sneaking affection for him.","cn":"以前她一直暗暗倾心于他。"}}]}},"snowfield":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"雪地;雪原","en":"A snowfield is a large area which is always covered in snow."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an area of land that is covered in snow","cn":"雪原﹐雪野"}]},"media":{"uk":"media/ldoce/hwd/bre/d/ld41snowfield.mp3","us":"media/ldoce/hwd/ame/4/snowfield.mp3"},"oxford":{"phon":"ˈsnəʊfiːld","pos":"noun","senses":[{"en":"a large area that is always covered with snow, for example in the mountains","cn":"雪原（终年积雪的地区）"}]}},"sneeze":{"collins":{"senses":[{"pos":"VERB 动词","cn":"打喷嚏","en":"When you sneeze, you suddenly take in your breath and then blow it down your nose noisily without being able to stop yourself, for example because you have a cold.","ex":{"en":"What exactly happens when we sneeze?","cn":"我们打喷嚏究竟是怎么回事？"}},{"pos":"PHRASE 短语","cn":"不容忽视;值得拥有","en":"If you say that something is not to be sneezed at, you mean that it is worth having.","ex":{"en":"The money's not to be sneezed at.","cn":"别把这笔钱不当回事。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if you sneeze, air suddenly comes from your nose, making a noise, for example when you have a cold","cn":"打喷嚏"},{"en":"used about an offer, especially of money, that is very good, and which you should consider carefully","cn":"不可轻视﹐值得认真考虑"},{"en":"the act or sound of sneezing","cn":"打喷嚏（声）"}]},"collocations":{"phrases":["ADV. loudly Someone sneezed loudly at the back of the hall.","VERB + SNEEZE make sb The smoke reached her and made her sneeze."]},"media":{"uk":"media/ldoce/hwd/bre/6/sneeze_v0205.mp3","us":"media/ldoce/hwd/ame/6/sneeze1.mp3"},"examples":[{"en":"In those days, $20 was not a sum to be sneezed at.","cn":"那时候，20 元可不能不当回事。"},{"en":"I've been sneezing all morning.","cn":"我一上午直打喷嚏。"}],"oxford":{"phon":"sniːz","pos":"verb","senses":[{"en":"to have air come suddenly and noisily out through your nose and mouth in a way that you cannot control, for example because you have a cold","cn":"打喷嚏","ex":{"en":"I've been sneezing all morning.","cn":"我一上午老是打喷嚏。"}},{"en":"the act of sneezing or the noise you make when you sneeze","cn":"喷嚏；喷嚏声","ex":{"en":"coughs and sneezes","cn":"咳嗽和喷嚏"},"pos":"noun"}]}},"sniper":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"狙击手","en":"A sniper is someone who shoots at people from a hidden position."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who uses a gun to kill someone - use this especially about a criminal or someone who is using a gun illegally","cn":""},{"en":"someone who hides, especially in a high place, and shoots at enemy soldiers","cn":""},{"en":"someone who is very well trained and very skilful at using a gun, either for sport or for their job with the army or the police","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/8/sniper0205.mp3","us":"media/ldoce/hwd/ame/c/laadsniper.mp3"},"oxford":{"phon":"ˈsnaɪpə(r)","pos":"noun","senses":[{"en":"a person who shoots at somebody from a hidden position","cn":"狙击手","ex":{"en":"Two soldiers were shot by snipers.","cn":"两个士兵被狙击手击中。"}}]}},"snowdrop":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"雪花莲(一种初春开放的小白花)","en":"A snowdrop is a small white flower which appears in the early spring."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a European plant with a small white flower which appears in early spring","cn":"雪花莲"}]},"media":{"uk":"media/ldoce/hwd/bre/8/snowdrop0205.mp3","us":"media/ldoce/hwd/ame/1/snowdrop.mp3"},"oxford":{"phon":"ˈsnəʊdrɒp","pos":"noun","senses":[{"en":"a small white flower that appears in early spring","cn":"雪花莲（早春开白花）"}]}},"snide":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"刻毒的;讽刺的;恶意的","en":"A snide comment or remark is one which criticizes someone in an unkind and often indirect way.","ex":{"en":"He made a snide comment about her weight","cn":"他说了一句很刻薄的话评论她的体重。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"something you say to someone that is unkind , makes them feel unhappy or upset","cn":""},{"en":"if you talk about someone behind their back , you say rude or unkind things about them when they are not present","cn":""},{"en":"criticizing someone or something in an unkind but clever way","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Snide means insulting or contemptuous in an indirect way. If your friend is wearing too much purple eye shadow and your other friend whispers to you, “What? Was she in a car wreck?” that’s a snide comment."}]},"media":{"uk":"media/ldoce/hwd/bre/e/snide0205.mp3","us":"media/ldoce/hwd/ame/6/snide.mp3"},"examples":[{"en":"snide comments/remarks","cn":"挖苦的议论/话语"}],"oxford":{"phon":"snaɪd","pos":"adjective","senses":[{"en":"criticizing somebody/something in an unkind and indirect way","cn":"讽刺的；挖苦的","ex":{"en":"snide comments/remarks","cn":"挖苦的议论／话语"}}]}},"snippet":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"小片;小部分;零星片段","en":"A snippet of something is a small piece of it.","ex":{"en":"...snippets of popular classical music","cn":"流行古典音乐的片段"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a small piece of news, information, or conversation 〔","cn":"新闻、信息或对话的〕一则，一条，片段"}]},"vocab":{"pos":"n","senses":[{"en":"A snippet is a tiny piece. You might only have time to read a snippet of \"Moby Dick\" before your early English class — just enough to know it's a book about a whale."}]},"collocations":{"phrases":["ADJ. little | interesting He passed on any interesting snippets of information he could glean from his colleagues.","VERB + SNIPPET gather, glean | give, pass on","PREP. ~ from The article gave a few snippets from her forthcoming memoirs. | ~ of a snippet of conversation"]},"media":{"uk":"media/ldoce/hwd/bre/a/snippet0205.mp3","us":"media/ldoce/hwd/ame/9/snippet.mp3"},"examples":[{"en":"Have you got any interesting snippets for me?","cn":"你有没有什么有趣的消息告诉我？"},{"en":"a snippet of information","cn":"一点消息"}],"oxford":{"phon":"ˈsnɪpɪt","pos":"noun","senses":[{"en":"a small piece of information or news","cn":"一小条（消息）；一则（新闻）","ex":{"en":"Have you got any interesting snippets for me?","cn":"你有没有什么有趣的消息告诉我？"}},{"en":"a short piece of a conversation, piece of music, etc.","cn":"一小段（谈话、音乐等）","ex":{"en":"snippets of dialogue from the TV show","cn":"该电视节目的对话片段"}}]}},"snot":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"鼻涕","en":"Snot is the substance that is produced inside your nose."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an impolite word for the thick mucus (= liquid ) produced in your nose","cn":"鼻涕〔不礼貌用语〕"},{"en":"someone who is snotty","cn":"高傲的人"}]},"vocab":{"pos":"n","senses":[{"en":"Snot is the discharge that comes from your nose when you have a bad cold. You'll want to carry tissues or a handkerchief with you when you're sneezing, to keep the snot contained."}]},"media":{"uk":"media/ldoce/hwd/bre/f/snot0205.mp3","us":"media/ldoce/hwd/ame/8/snot.mp3"},"examples":[{"en":"the little snot","cn":"那个妄自尊大的小人"}],"oxford":{"phon":"snɒt","pos":"noun","senses":[{"en":"a slightly rude word used to describe the liquid substance (= mucus) that is produced in the nose","cn":"鼻涕（有人认为是粗俗用语）"}]}},"snip":{"collins":{"senses":[{"pos":"VERB 动词","cn":"剪;剪下;剪断","en":"If you snip something, or if you snip at or through something, you cut it quickly using sharp scissors.","ex":{"en":"He has now begun to snip away at the piece of paper","cn":"现在他已经开始剪这张纸。"}},{"pos":"N-SING 单数名词","cn":"货真价实之物;物美价廉的物品","en":"If you say that something is a snip, you mean that it is very good value.","ex":{"en":"The beautifully made briefcase is a snip at £74.25.","cn":"这个做工精美的公文包售价才 74.25 英镑，可谓物美价廉。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to divide something into two or more pieces, especially using a knife or scissors","cn":""},{"en":"to quickly cut something, especially using scissors","cn":""},{"en":"to make a long narrow cut through something, especially using a knife","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/e/snip_v0205.mp3","us":"media/ldoce/hwd/ame/f/snip1.mp3"},"examples":[{"en":"It's a snip at only £25.","cn":"这个只卖 25 英镑，真是便宜。"},{"en":"She snipped at the loose threads hanging down.","cn":"她把垂下来的线头剪掉。"}],"oxford":{"phon":"snɪp","pos":"verb","senses":[{"en":"to cut something with scissors using short quick movements","cn":"（用剪刀快速）剪，剪断，剪开","ex":{"en":"Snip a tiny hole in the paper.","cn":"在纸上剪一个小孔。"}},{"en":"an act of cutting something with scissors; the sound that this makes","cn":"剪；剪东西的咔嚓声","g":"[countable]","ex":{"en":"Make a series of small snips along the edge of the fabric.","cn":"顺着布边细碎地剪。"},"pos":"noun"},{"en":"a tool like large scissors, used for cutting metal","cn":"（剪金属用的）平头剪","g":"[plural]","pos":"noun"},{"en":"a thing that is cheap and good value","cn":"价廉物美的东西；便宜货","g":"[singular]","lab":"British English, informal，，","ex":{"en":"It's a snip at only £25.","cn":"这个只卖 25 英镑，真是便宜。"},"pos":"noun"}]}},"snakebite":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"(尤指毒蛇的)蛇咬伤","en":"A snakebite is the bite of a snake, especially a poisonous one."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the bite of a poisonous snake","cn":"毒蛇咬伤"}]},"media":{"uk":"media/ldoce/hwd/bre/a/ld41snakebite.mp3","us":"media/ldoce/hwd/ame/b/snakebite.mp3"},"oxford":{"phon":"ˈsneɪkbaɪt","pos":"noun","senses":[{"en":"a wound that you get when a poisonous snake bites you","cn":"毒蛇咬伤","ex":{"en":"Three people have recently died from snakebites.","cn":"近来有三人死于毒蛇咬伤。"}},{"en":"an alcoholic drink made of equal parts of beer and cider","cn":"“蛇之吻”鸡尾酒（啤酒加苹果酒各半调制而成）"}]}},"snowball":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"雪球","en":"A snowball is a ball of snow. Children often throw snowballs at each other."},{"pos":"VERB 动词","cn":"(项目、运动等)迅速增长，滚雪球般增长","en":"If something such as a project or campaign snowballs, it rapidly increases and grows.","ex":{"en":"From those early days the business has snowballed","cn":"这个企业从早期开始就一直在迅速地发展扩大。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a ball of snow that children make and throw at each other","cn":""},{"en":"if something has a snowball effect, it starts a series of events or changes that all happen because of each other","cn":""},{"en":"to have no chance at all","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/3/snowball_v0205.mp3","us":"media/ldoce/hwd/ame/e/snowball1.mp3"},"examples":[{"en":"All this publicity has had a snowball effect on the sales of their latest album.","cn":"这些宣传对他们最新唱片的销售产生了一种滚雪球效应。"},{"en":"a snowball fight","cn":"雪仗"}],"oxford":{"phon":"ˈsnəʊbɔːl","pos":"noun","senses":[{"en":"a ball that you make out of snow to throw at somebody/something in a game","cn":"雪球","g":"[countable]","ex":{"en":"a snowball fight","cn":"雪仗"}},{"en":"a situation that develops more and more quickly as it continues","cn":"滚雪球般发展的情形","g":"[singular]","ex":{"en":"All this publicity has had a snowball effect on the sales of their latest album.","cn":"所有这些宣传对他们最新唱片的销售产生了一种滚雪球效应。"}},{"en":"a drink that is a mixture of lemonade and a liqueur (= a strong, sweet alcoholic drink) made with eggs","cn":"雪球鸡尾酒（含白兰地蛋酒和柠檬汽水）","g":"[countable]"},{"en":"if a problem, a plan, an activity, etc. snowballs, it quickly becomes much bigger, more serious, more important, etc.","cn":"滚雪球般迅速增大（或趋于严重、变得重要等）","ex":{"en":"Opposition to the proposals has snowballed.","cn":"对这些提议的反对意见如滚雪球般不断增加。"},"pos":"verb"}]}},"snapper":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"笛鲷;红鳍笛鲷","en":"A snapper is a fish that has sharp teeth and lives in warm seas."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a type of fish that lives in warm seas, often used as food","cn":"笛鲷〔产于热带海域的一种食用鱼〕"}]},"media":{"uk":"media/ldoce/hwd/bre/2/snapper0205.mp3","us":"media/ldoce/hwd/ame/b/snapper.mp3"},"oxford":{"phon":"ˈsnæpə(r)","pos":"noun","senses":[{"en":"a fish that lives in warm seas and is used for food","cn":"啮鱼（食用鱼，盛产于热带海域）","g":"[countable, uncountable]"},{"en":"a photographer, especially one who takes pictures of famous people for newspapers and magazines","cn":"（尤指为报章杂志拍摄名人照片的）摄影者","g":"[countable]","lab":"informal, British English，，"}]}},"snipe":{"collins":{"senses":[{"pos":"VERB 动词","cn":"批评;攻击;中伤","en":"If someone snipes at you, they criticize you.","ex":{"en":"The Spanish media were still sniping at the British press yesterday.","cn":"西班牙媒体昨天仍然在攻击英国媒体。"}},{"pos":"VERB 动词","cn":"狙击;放冷枪","en":"To snipe at someone means to shoot at them from a hidden position.","ex":{"en":"Gunmen have repeatedly sniped at US Army positions","cn":"持枪匪徒一再朝美军阵地放冷枪。"}},{"pos":"N-COUNT 可数名词","cn":"鹬;沙锥","en":"A snipe is a type of bird with a very long beak which lives in wet areas of land."}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to shoot from a hidden position at people who are not protected","cn":"伏击﹐狙击﹐打冷枪"},{"en":"to criticize someone in a nasty way","cn":"诽谤﹐中伤"},{"en":"a bird with a very long thin beak that lives in wet areas","cn":"沙锥〔嘴细长﹑栖于湿地的一种鸟〕"}]},"media":{"uk":"media/ldoce/hwd/bre/5/snipe_n0205.mp3","us":"media/ldoce/hwd/ame/6/snipe1.mp3"},"examples":[{"en":"Aid workers remain in the area despite continuous sniping.","cn":"尽管冷枪不断，但救援人员仍然留在这一地区。"},{"en":"Gunmen continued to snipe at people leaving their homes to find food.","cn":"枪手不断伏击外出找寻食物的人。"}],"oxford":{"phon":"snaɪp","pos":"verb","senses":[{"en":"to shoot at somebody from a hiding place, usually from a distance","cn":"狙击；打冷枪","g":"[intransitive]","ex":{"en":"Gunmen continued to snipe at people leaving their homes to find food.","cn":"枪手不断伏击外出找寻食物的人。"}},{"en":"to criticize somebody in an unpleasant way","cn":"冷言冷语地指摘；抨击","g":"[intransitive]"},{"en":"a bird with a long straight beak that lives on wet ground","cn":"沙锥（喙长直，生活在潮湿地区）","pos":"noun"}]}},"snag":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"小困难;小问题;不利条件","en":"A snag is a small problem or disadvantage.","ex":{"en":"A police clampdown on car thieves hit a snag when villains stole one of their cars","cn":"警方打击偷车贼的行动遭遇了一点小挫折：匪徒偷走了一辆警车。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(把)(尤指衣物)钩破;(使)绊住","en":"If you snag part of your clothing on a sharp or rough object or if it snags, it gets caught on the object and tears.","ex":{"en":"She snagged a heel on a root and tumbled to the ground","cn":"她脚后跟被一个树根绊了一下，踉踉跄跄地摔倒在地上。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a problem that stops you from making progress","cn":""},{"en":"a problem, especially one that you had not expected","cn":""},{"en":"a small problem that delays or prevents something","cn":""}]},"collocations":{"phrases":["ADJ. big, major | minor, small A minor snag is that it's expensive. | possible, potential | technical","VERB + SNAG hit We've hit a technical snag: the printer isn't compatible with my PC. | iron out There are a few snags to iron out before the","PREP. ~ in one of the snags in the scheme | ~ to There is a snag to the job: you have to work at weekends. | ~ with I suddenly saw the major"]},"media":{"uk":"media/ldoce/hwd/bre/9/snag_n0205.mp3","us":"media/ldoce/hwd/ame/9/snag1.mp3"},"examples":[{"en":"There is just one small snag — where is the money coming from?","cn":"只有一个小问题：钱从哪儿来？"},{"en":"Let me know if you run into any snags.","cn":"要是遇到什么麻烦就告诉我。"}],"oxford":{"phon":"snæɡ","pos":"noun","senses":[{"en":"a problem or difficulty, especially one that is small, hidden or unexpected","cn":"（尤指不严重的、潜在的、意外的）问题，困难，障碍，麻烦","lab":"informal","ex":{"en":"There is just one small snag—where is the money coming from?","cn":"只有一个小问题：钱从哪儿来？"}},{"en":"an object or a part of an object that is rough or sharp and may cut something","cn":"突出物；尖齿；尖角；尖刺","ex":{"en":"Check all surfaces for snags and rough edges.","cn":"检查所有表面是否有障碍物和粗糙边缘。"}},{"en":"a sausage","cn":"香肠","lab":"Australian English, New Zealand English, informal，，，，"},{"en":"to catch or tear something on something rough or sharp; to become caught or torn in this way","cn":"（在带尖的东西上）钩住，挂破，被钩住，被挂破","g":"[transitive, intransitive]","ex":{"en":"I snagged my sweater on the wire fence.","cn":"我的毛衣被铁丝网栅栏钩住了。"},"pos":"verb"},{"en":"to succeed in getting something quickly, often before other people","cn":"抓住；抢先获得","g":"[transitive]","lab":"North American English, informal，，","ex":{"en":"I snagged a ride from Joe.","cn":"我截住乔的车搭了一段路。"},"pos":"verb"}]}},"snowmobile":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"摩托雪橇;雪地机动车","en":"A snowmobile is a small vehicle built to move across snow and ice."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a small vehicle with a motor that moves over snow or ice easily","cn":"雪地机动车﹐摩托雪橇"}]},"media":{"uk":"media/ldoce/hwd/bre/9/ld41snowmobile.mp3","us":"media/ldoce/hwd/ame/7/snowmobile.mp3","img":["media/thumb/snowmobile.jpg"]},"oxford":{"phon":"ˈsnəʊməbiːl","pos":"noun","senses":[{"en":"a vehicle that can move over snow and ice easily","cn":"雪地摩托车"}]}},"snicker":{"collins":{"senses":[{"pos":"VERB 动词","cn":"窃笑;暗笑","en":"If you snicker, you laugh quietly in a disrespectful way, for example at something rude or embarrassing.","ex":{"en":"We all snickered at Mrs. Swenson.","cn":"我们都暗暗嘲笑斯温森太太。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to laugh quietly and in a way that is not nice at something which is not supposed to be funny","cn":"暗笑﹐窃笑"}]},"vocab":{"pos":"v n","senses":[{"en":"A snicker is a disrespectful snort of half-suppressed laughter, often expressing superiority. We snicker at beauty queens talking about world peace, for example."}]},"media":{"uk":"media/ldoce/hwd/bre/f/ld41snicker.mp3","us":"media/ldoce/hwd/ame/b/snicker1.mp3"},"examples":[{"en":"The other students snickered at Steve.","cn":"其他学生都偷偷地笑史蒂夫。"}],"oxford":{"phon":"ˈsnɪkə(r)","pos":"verb","senses":[{"en":"to laugh in a quiet unpleasant way, especially at something rude or at somebody’s problems or mistakes","cn":"窃笑；暗笑","ex":{"en":"Although his friends snickered, they were still impressed.","cn":"虽然他的朋友们暗自发笑，可他们还是被打动了。"}},{"en":"a quiet unpleasant laugh, especially at something rude or at somebody's problems or mistakes","cn":"窃笑；暗笑","pos":"noun"}]}},"snatch":{"collins":{"senses":[{"pos":"VERB 动词","cn":"一把抓住;迅速地夺取","en":"If you snatch something or snatch at something, you take it or pull it away quickly.","ex":{"en":"Mick snatched the cards from Archie's hand","cn":"米克一把夺过阿奇手里的牌。"}},{"pos":"VERB 动词","cn":"强抢;夺走","en":"If something is snatched from you, it is stolen, usually using force. If a person is snatched, they are taken away by force.","ex":{"en":"If your bag is snatched, let it go","cn":"要是有人抢你的包，就让他拿去。"}},{"pos":"VERB 动词","cn":"抓住(机会);抓紧时间(吃东西、休息等);抽空做","en":"If you snatch an opportunity, you take it quickly. If you snatch something to eat or a rest, you have it quickly in between doing other things.","ex":{"en":"I snatched a glance at the mirror","cn":"我乘机瞥了一眼镜子。"}},{"pos":"VERB 动词","cn":"侥幸获得(胜利);险胜","en":"If you snatch victory in a competition, you defeat your opponent by a small amount or just before the end of the contest.","ex":{"en":"The American came from behind to snatch victory by a mere eight seconds","cn":"美国人后来居上，仅以 8 秒钟的优势赢得了胜利。"}},{"pos":"N-COUNT 可数名词","cn":"(谈话或歌曲的)片段","en":"A snatch of a conversation or a song is a very small piece of it.","ex":{"en":"I heard snatches of the conversation.","cn":"我听见了一点谈话内容。"}},{"pos":"PHRASE 短语","cn":"反败为胜/反胜为败","en":"If someone snatches victory from the jaws of defeat, they win when it seems that they are certain to lose. If someone snatches defeat from the jaws of victory, they lose when it seems that they are certain to win."}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to sleep for a short time during the day","cn":""},{"en":"to sleep lightly for a short time, so that you wake up and go back to sleep again, often while you are sitting in a chair or when you do not intend to","cn":""},{"en":"to sleep for a short time, especially during the day when you do not usually sleep","cn":""}]},"vocab":{"pos":"v n","senses":[{"en":"When you snatch something, you grab it — either literally or figuratively. You might eagerly snatch the TV remote or your best friend's idea. Snatching can be nasty."}]},"collocations":{"phrases":["ADJ. brief","VERB + SNATCH catch, hear, overhear We caught snatches of conversation from the room next door. | hum, sing He was humming a snatch of a son","PREP. in ~es She learnt to sleep in brief snatches.","PHRASES a snatch of conversation/music/song"]},"media":{"uk":"media/ldoce/hwd/bre/d/snatch_v0205.mp3","us":"media/ldoce/hwd/ame/8/snatch1.mp3"},"examples":[{"en":"The raiders snatched $100 from the cash register.","cn":"劫匪从现金出纳机里抢走了 100 元。"},{"en":"The team snatched a dramatic victory in the last minute of the game.","cn":"该队在比赛的最后一分钟戏剧性地获胜。"}],"oxford":{"phon":"snætʃ","pos":"verb","senses":[{"en":"to take something quickly and often rudely or roughly","cn":"一把抓起；一下夺过","g":"[transitive, intransitive]","ex":{"en":"She managed to snatch the gun from his hand.","cn":"她设法从他手里夺过了枪。"}},{"en":"to take somebody/something away from a person or place, especially by force","cn":"夺去；抢走","g":"[transitive]","ex":{"en":"The raiders snatched $100 from the cash register.","cn":"劫匪从现金出纳机里抢走了 100 美元。"}},{"en":"to take or get something quickly, especially because you do not have much time","cn":"抓紧时间做；乘机获得","g":"[transitive]","ex":{"en":"I managed to snatch an hour's sleep.","cn":"我偷空儿睡了一小时的觉。"}},{"en":"a very small part of a conversation or some music that you hear","cn":"（听到的）只言片语，音乐片段","ex":{"en":"a snatch of music","cn":"音乐片段"},"pos":"noun"},{"en":"an act of moving your hand very quickly to take or steal something","cn":"抓；夺；抢夺；偷窃","ex":{"en":"a bag snatch","cn":"抢夺手提包"},"pos":"noun"},{"en":"a woman’s outer sex organs","cn":"（女性的）阴部","lab":"taboo, slang，，","pos":"noun"}]}},"snowboard":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"滑雪板","en":"A snowboard is a narrow board that you stand on in order to slide quickly down snowy slopes as a sport or for fun."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a long wide board made of plastic, which people stand on to go down snow-covered hills as a sport","cn":"滑雪板"}]},"vocab":{"pos":"n v","senses":[{"en":"A snowboard is very similar to a surfboard, but it's for standing on and sliding down a snowy mountain. If you visit a ski resort, you'll see many people zipping down the slopes on snowboards ."}]},"media":{"uk":"media/ldoce/hwd/bre/1/snowboard0205.mp3","us":"media/ldoce/hwd/ame/6/laadsnowboard.mp3"},"oxford":{"phon":"ˈsnəʊbɔːd","pos":"noun","senses":[{"en":"a long wide board that a person stands on to move over snow in the sport of snowboarding","cn":"滑雪板"}]}}});
